// ===================================================================
// 1. Data Types, Variables, and Go Version Map
// ===================================================================

/*
Start here: know the zero values, use := inside functions, and convert types
explicitly. In interviews, prefer int unless constraints require int64.

Go 1.18+: generics, any alias, comparable constraint
Go 1.20+: errors.Join, comparable types satisfy comparable constraints
Go 1.21+: built-in min/max/clear, slices/maps standard packages

Core declarations:

	var x int                 // zero value: 0
	x := 3                    // infer type inside a function
	const mod = 1_000_000_007 // Common prime modulus; use only when required.
	nums := []int{1, 2, 3}    // slice
	fixed := [3]int{1, 2, 3}  // array; length is part of the type
	count := map[string]int{} // map
	var wide int64 = int64(x) // conversions are explicit
	var small int32 = 32          // fixed-width signed integer
	var flags uint = 0b101        // unsigned integer, useful for bit masks
	maxInt := math.MaxInt         // finite sentinel for unreachable/best values
	letter := string(rune(65))    // "A": integer -> rune -> string
	_, _, _, _ = small, flags, maxInt, letter

Multiple assignment makes swaps easy: a, b = b, a.
Only bool values are conditions. Braces are required; semicolons are normally
inserted automatically.

The math.MaxInt line requires: import "math".
*/

// ===================================================================
// 2. Strings, Bytes, and Runes
// ===================================================================

// Use byte indexing for guaranteed ASCII input. Use range or []rune when a
// logical character may occupy multiple UTF-8 bytes. Strings are immutable.

// stringPatterns is a non-returning catalog of byte, rune, strings-package, and strconv
// operations; pass a non-empty string because the indexing examples intentionally show
// direct access.
// Requires: import "strconv"
// Requires: import "strings"
// Requires: import "unicode"
// Requires: import "unicode/utf8"
func stringPatterns(s string, nums []int) {
	// A string is immutable bytes, commonly UTF-8.
	byteLength := len(s)
	firstByte := s[0] // Panics if empty.
	prefix := s[:min(5, len(s))]
	suffix := s[min(5, len(s)):]
	middle := s[min(1, len(s)):min(5, len(s))]
	validUTF8 := utf8.ValidString(s)
	runeCount := utf8.RuneCountInString(s)

	// range decodes UTF-8 and yields byte index plus rune.
	for byteIndex, r := range s {
		_, _ = byteIndex, r
	}
	firstRuneIsUpper, firstRuneIsLower := false, false
	uppercasedFirstRune := rune(0)
	if len([]rune(s)) > 0 {
		first := []rune(s)[0]
		firstRuneIsUpper = unicode.IsUpper(first)
		firstRuneIsLower = unicode.IsLower(first)
		uppercasedFirstRune = unicode.ToUpper(first)
	}

	bytesCopy := []byte(s)
	runes := []rune(s)
	firstRune := runes[0] // Panics if there are no runes.
	reconstructed := string(runes)

	words := strings.Fields(s)
	csvParts := strings.Split(s, ",")
	joined := strings.Join(words, " ")
	contains := strings.Contains(s, "needle")
	firstIndex := strings.Index(s, "needle") // Byte index, -1 if absent.
	lastIndex := strings.LastIndex(s, "needle")
	repeated := strings.Repeat("go", 3)
	trimmedCutset := strings.Trim(s, "-_")
	count := strings.Count(s, "a")
	replacedOnce := strings.Replace(s, "old", "new", 1)
	replacedAll := strings.ReplaceAll(s, "old", "new")
	trimmed := strings.TrimSpace(s)
	lower := strings.ToLower(s)
	upper := strings.ToUpper(s)
	starts := strings.HasPrefix(s, "pre")
	ends := strings.HasSuffix(s, "suf")

	var builder strings.Builder
	for _, word := range words {
		if builder.Len() > 0 {
			builder.WriteByte(' ')
		}
		builder.WriteString(word)
	}
	built := builder.String()

	numberText := make([]string, len(nums))
	for i, value := range nums {
		numberText[i] = strconv.Itoa(value)
	}
	answerLine := strings.Join(numberText, ",")

	parsed, err := strconv.Atoi("42")
	parsed64, err64 := strconv.ParseInt("-42", 10, 64)
	parsedHex, hexErr := strconv.ParseInt("ff", 16, 64)
	formattedHex := strconv.FormatInt(255, 16)
	formatted := strconv.Itoa(parsed)

	_ = []any{
		byteLength, firstByte, prefix, suffix, middle, validUTF8, runeCount, bytesCopy,
		firstRune, reconstructed, csvParts, joined, contains,
		firstIndex, lastIndex, repeated, trimmedCutset, count, replacedOnce, replacedAll, trimmed,
		lower, upper, starts, ends, built, answerLine, parsed,
		err, parsed64, err64, parsedHex, hexErr, formattedHex, formatted,
		firstRuneIsUpper, firstRuneIsLower, uppercasedFirstRune,
	}
}

// normalizeLettersAndDigitsLowercase keeps Unicode letters and digits, lowercases
// letters, and removes every other rune.
// Requires: import "strings"
// Requires: import "unicode"
func normalizeLettersAndDigitsLowercase(s string) string {
	var builder strings.Builder
	for _, r := range s {
		if unicode.IsLetter(r) || unicode.IsDigit(r) {
			builder.WriteRune(unicode.ToLower(r))
		}
	}
	return builder.String()
}

// sortedRunesKey returns the input runes in sorted order. It is useful as a canonical
// key for grouping anagrams, not for locale-aware display ordering.
// Requires: import "slices"
func sortedRunesKey(s string) string {
	runes := []rune(s)
	slices.Sort(runes)
	return string(runes)
}

// ===================================================================
// 3. Arrays and Slices: Create -> Read -> Update -> Delete
// ===================================================================

/*
Master memory table:

| Operation       | slice               | map                 | set          |
|-----------------|---------------------|---------------------|--------------|
| Empty           | []T{} / make([]T,0) | make(map[K]V)       | map[T]struct |
| Add one         | append              | m[k] = v            | s[x]=struct{}|
| Add many        | append(a, b...)     | loop assignments    | loop         |
| Read            | a[i]                | v, ok := m[k]       | _, ok := s[x]|
| Remove          | reslice/copy trick  | delete(m, k)        | delete(s, x) |
| Empty all       | clear / a = a[:0]   | clear(m)            | clear(s)     |

Key caveats:

- Arrays copy by value. Slices are small headers pointing to backing arrays.
- Map reads return the value type's zero value when a key is absent.
- Use the comma-ok form when zero and missing mean different things.
- append may reuse the backing array or allocate a new one.
- Map iteration order is deliberately unspecified.
- nil slices can be read, ranged over, and appended to.
- Writing to a nil map panics; reading from it is safe.
*/

// sliceCreateReadUpdateDeleteExamples demonstrates creation, reads, copies, insertion,
// deletion, clearing, matrix allocation, and stack operations. Indexed examples require
// at least three input values.
// Requires: import "slices"
func sliceCreateReadUpdateDeleteExamples(n, rows, cols int, nums []int) {
	// The indexed read examples below require len(nums) >= 3.
	x := 2

	// CREATE
	var nilSlice []int
	empty := []int{}
	withLength := make([]int, n)
	withCapacity := make([]int, 0, n)
	fromData := []int{1, 2, 3}
	_ = [3]int{1, 2, 3} // Array, not slice.

	// Matrix create: each row gets its own backing array.
	grid := make([][]int, rows)
	for r := range grid {
		grid[r] = make([]int, cols)
	}

	// READ
	first := nums[0] // Panics if empty.
	last := nums[len(nums)-1]
	middle := nums[1:3] // View sharing the backing array.
	size := len(nums)
	capacity := cap(nums)
	firstX := slices.Index(nums, x) // -1 if absent.
	containsX := slices.Contains(nums, x)

	// COPY
	copy1 := slices.Clone(nums)
	copy2 := append([]int(nil), nums...)
	copy3 := make([]int, len(nums))
	copy(copy3, nums)

	matrixCopy := make([][]int, len(grid))
	for r := range grid {
		matrixCopy[r] = slices.Clone(grid[r])
	}

	// UPDATE / ADD
	withCapacity = append(withCapacity, x)
	withCapacity = append(withCapacity, 4, 5)
	withCapacity = append(withCapacity, nums...)
	nums[0] = 99
	slices.Sort(nums)    // In-place ascending.
	slices.Reverse(nums) // In-place.

	// Insert x before index i.
	i := min(1, len(withCapacity))
	withCapacity = append(withCapacity, 0)
	copy(withCapacity[i+1:], withCapacity[i:])
	withCapacity[i] = x

	// DELETE while preserving order.
	if len(withCapacity) > 0 {
		i = 0
		copy(withCapacity[i:], withCapacity[i+1:])
		withCapacity = withCapacity[:len(withCapacity)-1]
	}

	// DELETE without preserving order, O(1).
	if len(fromData) > 0 {
		i = 0
		fromData[i] = fromData[len(fromData)-1]
		fromData = fromData[:len(fromData)-1]
	}

	clear(withLength)           // Zero elements; length is unchanged.
	withLength = withLength[:0] // Empty but retain capacity.
	nilSlice = nil              // Release reference to backing array.

	// Stack: append and trim the right end.
	stack := []int{1, 2}
	popped := stack[len(stack)-1]
	stack = stack[:len(stack)-1]

	_ = []any{
		nilSlice, empty, first, last, middle, size, capacity,
		firstX, containsX, copy1, copy2, copy3, matrixCopy,
		popped, stack,
	}
}

// asciiDigitValue converts one ASCII byte '0' through '9' to its integer value.
// It deliberately does not accept non-ASCII Unicode digits.
func asciiDigitValue(character byte) (int, bool) {
	if character < '0' || character > '9' {
		return 0, false
	}
	return int(character - '0'), true
}

// fillAndReverseSlice demonstrates index-based mutation without a library.
func fillAndReverseSlice(values []int, fillValue int) {
	for index := range values {
		values[index] = fillValue
	}
	for left, right := 0, len(values)-1; left < right; left, right = left+1, right-1 {
		values[left], values[right] = values[right], values[left]
	}
}

// ===================================================================
// 4. Maps
// ===================================================================

// Map reads are safe on nil maps, but writes panic. The comma-ok form separates
// a missing key from a stored zero value. Map iteration order is unspecified.

// mapCreateReadUpdateDeleteExamples demonstrates initialization, comma-ok lookup,
// counting, grouping, cloning, deletion, clearing, and safe reads from a nil map.
// Requires via helper: import "slices"
// Requires: import "maps"
func mapCreateReadUpdateDeleteExamples(words []string, nums []int) {
	// CREATE
	var nilMap map[string]int
	counts := make(map[string]int)
	withData := map[string]int{"a": 1, "b": 2}

	// READ
	value := withData["a"]
	missingZero := withData["missing"]
	value, exists := withData["a"]
	size := len(withData)
	_, contains := withData["a"]

	// UPDATE / ADD
	counts["c"] = 3
	for _, word := range words {
		counts[word]++ // Missing key starts at int's zero value.
	}

	clone := maps.Clone(withData)
	for key, value := range counts {
		clone[key] = value
	}

	// Grouping.
	groups := make(map[string][]string)
	for _, word := range words {
		key := sortedRunesKey(word)
		groups[key] = append(groups[key], word)
	}

	// Frequency counting.
	frequency := make(map[int]int)
	for _, x := range nums {
		frequency[x]++
	}

	// DELETE
	delete(counts, "c") // No-op when absent.
	removed, ok := counts["x"]
	if ok {
		delete(counts, "x")
	}
	clear(counts)

	// Safe: reads from nil maps return zero. Unsafe: nilMap["x"] = 1.
	nilRead := nilMap["x"]

	_ = []any{
		value, missingZero, exists, size, contains, clone, groups,
		frequency, removed, nilRead,
	}
}

// mapIterationExamples shows all three useful range forms. Map order is not
// stable, so collect and sort keys when output order matters.
func mapIterationExamples(counts map[string]int) {
	for key, value := range counts {
		_, _ = key, value
	}
	for key := range counts {
		_ = key
	}
	for _, value := range counts {
		_ = value
	}
}

// ===================================================================
// 5. Structs and Common Interview Node Types
// ===================================================================

// Struct values copy on assignment. Use pointers for linked structures and
// mutation; use comparable value structs such as Point as map keys.

// Interval stores two endpoints. Each interval algorithm below states whether
// it treats end as inclusive or exclusive; do not mix those conventions.
type Interval struct {
	start int
	end   int
}

// ListNode matches the singly linked-list shape used by LeetCode prompts.
type ListNode struct {
	Val  int
	Next *ListNode
}

// TreeNode matches the binary-tree shape used by LeetCode prompts.
type TreeNode struct {
	Val   int
	Left  *TreeNode
	Right *TreeNode
}

type Point struct {
	Row int
	Col int
}

// newListNode is a small constructor for the pointer shape used by LeetCode.
func newListNode(value int) *ListNode {
	return &ListNode{Val: value}
}

// anonymousPairExample shows a one-off record type. Prefer a named type when
// methods, reuse, or package-level documentation would make the meaning clearer.
func anonymousPairExample(value, priority int) struct {
	value    int
	priority int
} {
	return struct {
		value    int
		priority int
	}{value: value, priority: priority}
}

// ===================================================================
// 6. Control Flow and Iteration
// ===================================================================

// Go uses for for every loop shape: `for condition {}` replaces while, and
// `for {}` is an intentional infinite loop exited with break or return. Switch
// cases stop automatically, and only explicit bool expressions can be conditions.

// findMatrixValue demonstrates the one Go control-flow tool that is easy to
// forget in interviews: a label can leave nested loops in one step.
func findMatrixValue(matrix [][]int, target int) (row, col int, found bool) {
	row, col = -1, -1
search:
	for r := range matrix {
		for c, value := range matrix[r] {
			if value == target {
				row, col, found = r, c, true
				break search
			}
		}
	}
	return row, col, found
}

// iterationPatterns compares index/value ranges, reverse iteration, nested matrix
// loops, range-copy mutation, closure capture, and deterministic map-key ordering.
// Requires: import "slices"
func iterationPatterns(nums []int, matrix [][]int) {
	for index, value := range nums {
		_, _ = index, value
	}

	for index := range nums {
		_ = index
	}

	for index := len(nums) - 1; index >= 0; index-- {
		_ = nums[index]
	}

	for row := range matrix {
		for col := range matrix[row] {
			_ = matrix[row][col]
		}
	}

	// range copies each element into value. Mutate through nums[i].
	for i := range nums {
		nums[i] *= 2
	}

	// Before Go 1.22, closures could accidentally capture the reused range
	// variable. Rebinding remains clear and portable interview code.
	functions := make([]func() int, 0, len(nums))
	for _, value := range nums {
		value := value
		functions = append(functions, func() int { return value })
	}

	// Maps are unordered. Sort keys for deterministic output.
	counts := map[string]int{"b": 2, "a": 1}
	keys := make([]string, 0, len(counts))
	for key := range counts {
		keys = append(keys, key)
	}
	slices.Sort(keys)

	_ = []any{functions, keys}
}

// controlFlowExamples collects loop and switch forms that are easy to forget.
func controlFlowExamples(value, limit int) string {
	for index := 0; index < limit; index += 2 { // Classic loop with step 2.
		if index == value {
			break
		}
	}
	for value < 0 { // Go's while-style loop.
		value++
	}
	if parsed := value * 2; parsed > limit { // Initializer is scoped to if/else.
		return "large"
	}
	switch { // A switch without a value replaces a long if/else chain.
	case value < 0:
		return "negative"
	case value == 0:
		return "zero"
	default:
		return "positive"
	}
}

// ===================================================================
// 7. Functions, Closures, Errors, and Defer
// ===================================================================

// variadicSum adds zero or more integer arguments. A slice is expanded into variadic
// arguments with values....
func variadicSum(values ...int) int {
	total := 0
	for _, value := range values {
		total += value
	}
	return total
}

// namedAndFirstClassFunctions demonstrates assigning an anonymous function to a
// variable, calling it through another variable, and expanding a slice into variadic
// arguments.
func namedAndFirstClassFunctions(nums []int) {
	add := func(a, b int) int { return a + b }
	operation := add
	result := operation(2, 3)
	total := variadicSum(nums...)
	_ = []any{result, total}
}

// makeCounter returns a closure that retains and increments its own count across calls.
func makeCounter() func() int {
	count := 0
	return func() int {
		count++
		return count
	}
}

// divide performs integer division and returns an error instead of panicking when the
// divisor is zero.
// Requires: import "errors"
func divide(a, b int) (int, error) {
	if b == 0 {
		return 0, errors.New("division by zero")
	}
	return a / b, nil
}

// parsePositive converts decimal text to an integer, wraps conversion errors with
// context, and rejects zero or negative results.
// Requires: import "fmt"
// Requires: import "strconv"
func parsePositive(text string) (int, error) {
	value, err := strconv.Atoi(text)
	if err != nil {
		return 0, fmt.Errorf("parse %q: %w", text, err)
	}
	if value <= 0 {
		return 0, fmt.Errorf("value must be positive: %d", value)
	}
	return value, nil
}

// readAndClose reads a file and joins any close failure with an earlier read failure.
// The named error result lets the deferred cleanup update the returned error.
// Requires: import "errors"
// Requires: import "io"
// Requires: import "os"
func readAndClose(path string) (_ []byte, err error) {
	file, err := os.Open(path)
	if err != nil {
		return nil, err
	}
	defer func() {
		err = errors.Join(err, file.Close())
	}()
	return io.ReadAll(file)
}

/*
defer notes:

- Deferred calls run last-in-first-out (LIFO) when the function returns.
- Arguments are evaluated when defer is registered.
- Use defer for cleanup after successfully acquiring a resource.
- panic/recover is not ordinary error handling; return errors instead.
*/

// minAndMaxValues demonstrates multiple return values. The bool is false for
// empty input because no minimum or maximum exists.
func minAndMaxValues(values []int) (minimum, maximum int, ok bool) {
	if len(values) == 0 {
		return 0, 0, false
	}
	minimum, maximum = values[0], values[0]
	for _, value := range values[1:] {
		minimum = min(minimum, value)
		maximum = max(maximum, value)
	}
	return minimum, maximum, true
}

// fibonacciRecursiveTeaching is intentionally exponential: it demonstrates
// recursive syntax, not the implementation to choose for large n.
func fibonacciRecursiveTeaching(n int) int {
	if n <= 1 {
		return max(n, 0)
	}
	return fibonacciRecursiveTeaching(n-1) + fibonacciRecursiveTeaching(n-2)
}

// ===================================================================
// 8. Sorting
// ===================================================================

// Sort a copy unless mutation is intended. Prefer cmp.Compare over subtraction
// in comparators, and state which bound your binary search returns.

type ScoreRecord struct {
	name  string
	score int
	age   int
}

// sortingPatterns demonstrates copied ascending/descending sorts, multi-key comparison,
// and stable sorting. The record slice is sorted in place.
// Requires: import "cmp"
// Requires: import "slices"
// Requires: import "sort"
func sortingPatterns(nums []int, words []string, records []ScoreRecord) {
	sortedNums := slices.Clone(nums)
	slices.Sort(sortedNums)
	slices.SortFunc(sortedNums, func(a, b int) int {
		return cmp.Compare(b, a) // Descending without subtraction overflow.
	})

	sortedWords := slices.Clone(words)
	slices.SortFunc(sortedWords, func(a, b string) int {
		if len(a) != len(b) {
			return cmp.Compare(len(a), len(b))
		}
		return cmp.Compare(a, b)
	})

	// score descending, then name ascending.
	sort.Slice(records, func(i, j int) bool {
		if records[i].score != records[j].score {
			return records[i].score > records[j].score
		}
		return records[i].name < records[j].name
	})

	// Stable sort preserves earlier order for equal keys.
	sort.SliceStable(records, func(i, j int) bool {
		return records[i].age < records[j].age
	})

	_ = []any{sortedNums, sortedWords}
}

// legacySortPackageExamples shows APIs common in code written before Go 1.21.
// New Go code can usually use slices.Sort and slices.IsSorted instead.
// Requires: import "sort"
func legacySortPackageExamples(values []int, words []string) bool {
	sort.Ints(values)
	sort.Strings(words)
	intValuesAreSorted := sort.IntsAreSorted(values)
	wordsAreSorted := sort.StringsAreSorted(words)
	valuesAreSortedByComparator := sort.SliceIsSorted(values, func(i, j int) bool {
		return values[i] < values[j]
	})
	return intValuesAreSorted && wordsAreSorted && valuesAreSortedByComparator
}

// ===================================================================
// 9. Binary Search
// ===================================================================

// binarySearchLibrary returns the insertion index and exact-match flag from
// slices.BinarySearch; input must be ascending.
// Requires: import "slices"
func binarySearchLibrary(sortedNums []int, target int) (int, bool) {
	index, found := slices.BinarySearch(sortedNums, target)
	return index, found
}

// firstIndexAtLeastTargetUsingSortSearch returns the first index whose value is greater
// than or equal to target, possibly len(input). Input must be ascending.
// Requires: import "sort"
func firstIndexAtLeastTargetUsingSortSearch(sortedNums []int, target int) int {
	// First index i where sortedNums[i] >= target.
	return sort.Search(len(sortedNums), func(i int) bool {
		return sortedNums[i] >= target
	})
}

// firstIndexGreaterThanTargetUsingSortSearch returns the first index whose value is
// strictly greater than target, possibly len(input). Input must be ascending.
// Requires: import "sort"
func firstIndexGreaterThanTargetUsingSortSearch(sortedNums []int, target int) int {
	// First index i where sortedNums[i] > target.
	return sort.Search(len(sortedNums), func(i int) bool {
		return sortedNums[i] > target
	})
}

// firstIndexAtLeastTarget manually implements a half-open [left,right) lower-bound
// search and returns the first value greater than or equal to target.
func firstIndexAtLeastTarget(nums []int, target int) int {
	left, right := 0, len(nums)
	for left < right {
		middle := left + (right-left)/2
		if nums[middle] < target {
			left = middle + 1
		} else {
			right = middle
		}
	}
	return left
}

// Count in sorted data by subtracting the first index > target from the first
// index >= target. This is O(log n), unlike scanning after one match.
// Requires via helper: import "sort"
func countOccurrences(sortedNums []int, target int) int {
	return firstIndexGreaterThanTargetUsingSortSearch(sortedNums, target) -
		firstIndexAtLeastTargetUsingSortSearch(sortedNums, target)
}

// exactIndexBinarySearchClosedInterval searches [left, right], including both
// endpoints. It returns -1 when target is absent. Time O(log n), space O(1).
func exactIndexBinarySearchClosedInterval(sortedValues []int, target int) int {
	left, right := 0, len(sortedValues)-1
	for left <= right {
		middle := left + (right-left)/2
		if sortedValues[middle] == target {
			return middle
		}
		if sortedValues[middle] < target {
			left = middle + 1
		} else {
			right = middle - 1
		}
	}
	return -1
}

// legacySearchIntsExample returns the insertion index used by sort.SearchInts.
// Requires: import "sort"
func legacySearchIntsExample(sortedValues []int, target int) (index int, found bool) {
	index = sort.SearchInts(sortedValues, target)
	return index, index < len(sortedValues) && sortedValues[index] == target
}

// ===================================================================
// 10. Stack and Queue
// ===================================================================

// A slice handles stacks directly. For queues, a head index is a strong default.
// container/heap is verbose because the type owns ordering through Less.

// queueWithHeadIndexExample demonstrates amortized O(1) dequeue with a monotonically
// increasing head index. It returns the unconsumed suffix.
func queueWithHeadIndexExample(values []int) []int {
	// A slice plus a head index gives amortized O(1) dequeue.
	queue := append([]int(nil), values...)
	head := 0
	queue = append(queue, 42)
	if head < len(queue) {
		front := queue[head]
		queue[head] = 0 // Release references here for pointer element types.
		head++
		_ = front
	}
	return queue[head:]
}

// stackOperationsExample demonstrates last-in-first-out stack operations with
// a slice. Push with append; the final index peeks; shortening by one pops.
func stackOperationsExample(values []int) (top int, remaining []int, ok bool) {
	stack := append([]int(nil), values...)
	if len(stack) == 0 {
		return 0, stack, false
	}
	top = stack[len(stack)-1]
	stack = stack[:len(stack)-1]
	return top, stack, true
}

// ===================================================================
// 11. Heap and Priority Queue
// ===================================================================

/*
container/heap does not provide a concrete heap type. A type supplies five
methods: Len, Less, Swap, Push, and Pop. The package uses Len/Less/Swap to
restore heap order. Its heap.Pop first moves the root to the slice's end, then
calls this type's Pop method to remove that final element. That is why Pop below
removes the last slice item rather than index zero.
*/

// IntegerMinHeap is a min-heap. Reverse Less for a max-heap.
type IntegerMinHeap []int

// Len returns the number of stored values for heap.Interface.
func (h IntegerMinHeap) Len() int { return len(h) }

// Less gives smaller integers higher priority; reverse < for a max-heap.
func (h IntegerMinHeap) Less(i, j int) bool { return h[i] < h[j] }

// Swap exchanges positions while the heap package restores ordering.
func (h IntegerMinHeap) Swap(i, j int) { h[i], h[j] = h[j], h[i] }

// Push appends the concrete int passed through heap.Push's any parameter.
func (h *IntegerMinHeap) Push(value any) {
	*h = append(*h, value.(int))
}

// Pop removes the final item after the heap package has moved the root there.
func (h *IntegerMinHeap) Pop() any {
	old := *h
	n := len(old)
	value := old[n-1]
	*h = old[:n-1]
	return value
}

// heapOperationsExample demonstrates initialization, insertion, root peek, removal with
// a type assertion, priority repair, arbitrary removal, and clearing.
// Requires: import "container/heap"
// Requires: import "slices"
func heapOperationsExample(nums []int) {
	h := IntegerMinHeap(slices.Clone(nums))
	heap.Init(&h)     // O(n).
	heap.Push(&h, 42) // O(log n).
	smallest := h[0]  // Peek, O(1); requires non-empty heap.
	popped := heap.Pop(&h).(int)
	if len(h) > 0 {
		h[0]++          // Example priority change.
		heap.Fix(&h, 0) // Restore after changing h[0].
		heap.Remove(&h, 0)
	}
	clear(h)
	h = h[:0]
	_ = []any{smallest, popped}
}

// drainQueueByReslicing shows the concise queue form often used in short
// interview solutions. For long-lived queues, prefer the head-index form in
// queueWithHeadIndexExample and compact explicitly when the consumed prefix grows.
// Requires: import "slices"
func drainQueueByReslicing(values []int) []int {
	queue := slices.Clone(values)
	result := make([]int, 0, len(queue))
	for len(queue) > 0 {
		front := queue[0]
		queue[0] = 0 // Drop references early when T contains pointers.
		queue = queue[1:]
		result = append(result, front)
	}
	return result
}

// PriorityItem pairs a payload with an integer priority. PriorityItemHeap is a
// min-heap, so heap.Pop removes the item with the smallest priority first.
// If priorities never change and repeated insertion is unnecessary, sorting a
// slice once can be a simpler interview solution than implementing a heap.
type PriorityItem struct {
	value    int
	priority int
}

type PriorityItemHeap []PriorityItem

// These five methods implement heap.Interface for PriorityItem values.
func (h PriorityItemHeap) Len() int { return len(h) }

// Less defines which of two elements has higher heap priority.
func (h PriorityItemHeap) Less(i, j int) bool { return h[i].priority < h[j].priority }

// Swap exchanges two heap positions while container/heap restores its invariant.
func (h PriorityItemHeap) Swap(i, j int) { h[i], h[j] = h[j], h[i] }

// Push appends a concrete value received through heap.Interface's any parameter.
func (h *PriorityItemHeap) Push(value any) {
	*h = append(*h, value.(PriorityItem))
}

// Pop removes the final slice item after container/heap has moved the root there.
func (h *PriorityItemHeap) Pop() any {
	old := *h
	last := old[len(old)-1]
	*h = old[:len(old)-1]
	return last
}

// kLargestValues keeps only k candidates in a min-heap. The root is the
// smallest retained value, so any extra item can be discarded in O(log k).
// Total time O(n log k), extra space O(k). Result order is unspecified.
// Requires: import "container/heap"
// Requires: import "slices"
func kLargestValues(values []int, k int) []int {
	if k <= 0 {
		return nil
	}
	priorityQueue := &IntegerMinHeap{}
	for _, value := range values {
		heap.Push(priorityQueue, value)
		if priorityQueue.Len() > k {
			heap.Pop(priorityQueue)
		}
	}
	return slices.Clone(*priorityQueue)
}

// ===================================================================
// 12. Sets via Maps
// ===================================================================

/*
Go has no built-in set. Choose one of these map representations:

	map[T]bool       // simpler membership: if set[value] { ... }
	map[T]struct{}   // stores keys with a zero-size value; use comma-ok

A missing bool map entry reads as false. That makes membership concise, but a
stored false is indistinguishable from absence unless comma-ok is also used.
The struct form communicates that only keys matter.
*/

// setCreateReadUpdateDeleteExamples demonstrates a key-only set implemented by
// map[int]struct{}.
func setCreateReadUpdateDeleteExamples(nums []int) {
	set := make(map[int]struct{}, len(nums))
	for _, value := range nums {
		set[value] = struct{}{}
	}
	set[42] = struct{}{}
	_, exists := set[42]
	delete(set, 42)
	size := len(set)
	clear(set)
	_ = []any{exists, size}
}

// Set algebra follows the operation names directly. map[T]struct{} avoids a
// redundant bool value; use map[T]bool when the shorter membership check wins.
func setUnion(left, right map[int]struct{}) map[int]struct{} {
	result := make(map[int]struct{}, len(left)+len(right))
	for value := range left {
		result[value] = struct{}{}
	}
	for value := range right {
		result[value] = struct{}{}
	}
	return result
}

// setIntersection returns values present in both sets. Iterating the smaller set
// reduces membership checks.
func setIntersection(left, right map[int]struct{}) map[int]struct{} {
	if len(left) > len(right) {
		left, right = right, left
	}
	result := make(map[int]struct{})
	for value := range left {
		if _, exists := right[value]; exists {
			result[value] = struct{}{}
		}
	}
	return result
}

// setDifference returns values present in left but absent from right.
func setDifference(left, right map[int]struct{}) map[int]struct{} {
	result := make(map[int]struct{}, len(left))
	for value := range left {
		if _, exists := right[value]; !exists {
			result[value] = struct{}{}
		}
	}
	return result
}

// boolSetExamples demonstrates the concise bool representation.
func boolSetExamples(values []int, target int) (map[int]bool, bool) {
	set := make(map[int]bool, len(values))
	for _, value := range values {
		set[value] = true
	}
	containsTarget := set[target] // Missing keys read as false.
	delete(set, target)
	return set, containsTarget
}

// sliceToSet builds the struct representation from a slice in O(n) time.
func sliceToSet(values []int) map[int]struct{} {
	set := make(map[int]struct{}, len(values))
	for _, value := range values {
		set[value] = struct{}{}
	}
	return set
}

// ===================================================================
// 13. Math and Numbers
// ===================================================================

// numberAndMathExamples shows common numeric helpers. The math package uses
// float64; Go 1.21 built-ins min and max work directly with integers.
// Requires: import "math"
func numberAndMathExamples(a, b, n int) {
	absolute := a
	if absolute < 0 {
		absolute = -absolute
	}
	clamped := max(0, min(n, 100))
	quotient, remainder, nonNegativeRemainder := 0, 0, 0
	if b != 0 {
		quotient = a / b // Integer division truncates toward zero.
		remainder = a % b
		nonNegativeRemainder = ((remainder % b) + b) % b
	}
	squareRoot := math.Sqrt(float64(max(n, 0)))
	floor, ceiling := math.Floor(squareRoot), math.Ceil(squareRoot)
	absoluteFloat := math.Abs(float64(a))
	power := math.Pow(2, 10)
	baseTwoLogarithm := math.Log2(max(power, 1))
	_ = []any{absolute, clamped, quotient, remainder, nonNegativeRemainder, squareRoot, floor, ceiling, absoluteFloat, power, baseTwoLogarithm, math.MaxInt}
}

// integerSquareRoot returns floor(sqrt(n)). It avoids floating-point rounding.
func integerSquareRoot(n int) int {
	if n < 0 {
		return -1
	}
	left, right := 0, n
	for left <= right {
		middle := left + (right-left)/2
		if middle != 0 && middle > n/middle {
			right = middle - 1
		} else {
			left = middle + 1
		}
	}
	return right
}

// greatestCommonDivisor returns the largest non-negative integer that divides both
// inputs without a remainder. Euclid's algorithm repeatedly replaces (a, b) with (b,
// a%b), which preserves their common divisors. Time O(log min(|a|, |b|)); space O(1).
func greatestCommonDivisor(a, b int) int {
	if a < 0 {
		a = -a
	}
	if b < 0 {
		b = -b
	}
	for b != 0 {
		a, b = b, a%b
	}
	return a
}

// leastCommonMultiple returns the smallest non-negative integer divisible by
// both inputs. The identity “least common multiple * greatest common divisor =
// |a*b|” avoids searching through multiples. Time is dominated by
// greatestCommonDivisor.
func leastCommonMultiple(a, b int) int {
	if a == 0 || b == 0 {
		return 0
	}
	value := (a / greatestCommonDivisor(a, b)) * b // Divide first to reduce overflow risk.
	if value < 0 {
		value = -value
	}
	return value
}

// modularPowerUsingBinaryExponentiation computes base^exponent mod modulus in O(log exponent).
func modularPowerUsingBinaryExponentiation(base, exponent, modulus int64) int64 {
	if exponent < 0 || modulus <= 0 {
		return 0
	}
	base = ((base % modulus) + modulus) % modulus
	result := int64(1 % modulus)
	for exponent > 0 {
		if exponent&1 == 1 {
			result = result * base % modulus
		}
		base = base * base % modulus
		exponent >>= 1
	}
	return result
}

// ===================================================================
// 14. Bit Manipulation
// ===================================================================

// bitManipulationExamples demonstrates read, set, clear, and toggle operations.
// Requires: import "math/bits"
func bitManipulationExamples(mask uint) {
	mask |= 1 << 3
	hasBit := mask&(1<<3) != 0
	isOdd := mask&1 == 1
	mask &^= 1 << 3 // &^ means AND NOT; it clears selected bits.
	mask ^= 1 << 3
	clearedLowestSetBit := mask & (mask - 1)
	isolatedLowestSetBit := mask & -mask
	setBitCount := bits.OnesCount(mask)
	bitLength := bits.Len(mask)
	trailingZeroCount := bits.TrailingZeros(mask)
	leadingZeroCount := bits.LeadingZeros(mask)
	_ = []any{hasBit, isOdd, clearedLowestSetBit, isolatedLowestSetBit, setBitCount, bitLength, trailingZeroCount, leadingZeroCount}
}

// isPowerOfTwo is true when a positive value has exactly one set bit.
func isPowerOfTwo(value uint) bool {
	return value != 0 && value&(value-1) == 0
}

// allSubsetsUsingBitmask maps each bit to one input position. It is compact and useful
// when n is small enough for O(n*2^n) enumeration.
// Requires: import "math/bits"
func allSubsetsUsingBitmask(nums []int) [][]int {
	if len(nums) >= bits.UintSize {
		return nil
	}
	answer := make([][]int, 0, 1<<len(nums))
	for mask := 0; mask < 1<<len(nums); mask++ {
		subset := make([]int, 0, bits.OnesCount(uint(mask)))
		for index, value := range nums {
			if mask&(1<<index) != 0 {
				subset = append(subset, value)
			}
		}
		answer = append(answer, subset)
	}
	return answer
}

// ===================================================================
// 15. Core Algorithm Templates
// ===================================================================

// Learn the trigger for each family, then copy the smallest template that fits.
// Detailed variants live in Appendix D.
// Fixed-length sliding window: maximumSumFixedLengthWindow in D.3.
// Fast/slow pointers: linkedListHasCycleUsingFloydAlgorithm in D.2.
// Memoized dynamic programming: countGridPathsUsingMemoization in D.11.

// -------------------------------------------------------------------
// 15.1 Hash Map and Counting (companion: algorithms/001-hash-map-and-counting.go)
// -------------------------------------------------------------------

// twoSumIndicesUsingMap returns indices of two values whose sum is target, or nil when
// no pair exists. The map stores each previously seen value's index, so target-current
// can be checked before current is inserted. Time O(n); extra space O(n).
func twoSumIndicesUsingMap(nums []int, target int) []int {
	seen := make(map[int]int, len(nums))
	for index, value := range nums {
		if otherIndex, ok := seen[target-value]; ok {
			return []int{otherIndex, index}
		}
		seen[value] = index
	}
	return nil
}

// -------------------------------------------------------------------
// 15.2 Two Pointers (companion: algorithms/002-two-pointers.go)
// -------------------------------------------------------------------

// sortedTwoSumIndicesUsingTwoPointers requires ascending input. If the current sum is
// too small only the left pointer can increase it; if too large only the right pointer
// can decrease it. It returns two indices or nil. Time O(n); space O(1).
func sortedTwoSumIndicesUsingTwoPointers(nums []int, target int) []int {
	left, right := 0, len(nums)-1
	for left < right {
		total := nums[left] + nums[right]
		switch {
		case total == target:
			return []int{left, right}
		case total < target:
			left++
		default:
			right--
		}
	}
	return nil
}

// -------------------------------------------------------------------
// 15.3 Sliding Window (companion: algorithms/003-sliding-window.go)
// -------------------------------------------------------------------

// countSubarraysWithAtMostKDistinctValues counts contiguous subarrays containing no
// more than k distinct numbers. The window [left,right] is shrunk until valid; every
// suffix ending at right and starting from left through right is then valid,
// contributing right-left+1. Time O(n); extra space O(k).
func countSubarraysWithAtMostKDistinctValues(nums []int, k int) int {
	if k < 0 {
		return 0
	}
	count := make(map[int]int)
	left, total := 0, 0
	for right, value := range nums {
		count[value]++
		for len(count) > k {
			leftValue := nums[left]
			count[leftValue]--
			if count[leftValue] == 0 {
				delete(count, leftValue)
			}
			left++
		}
		total += right - left + 1
	}
	return total
}

// -------------------------------------------------------------------
// 15.4 Binary Search on Answer (companion: algorithms/004-binary-search.go)
// -------------------------------------------------------------------

// smallestFeasibleValueUsingBinarySearch requires a monotonic predicate: once
// can(value) becomes true, it must stay true for all larger values. It returns the
// first true value in the inclusive range [low,high]. Time O(log(high-low)) predicate
// calls; space O(1).
func smallestFeasibleValueUsingBinarySearch(low, high int, can func(int) bool) int {
	for low < high {
		middle := low + (high-low)/2
		if can(middle) {
			high = middle
		} else {
			low = middle + 1
		}
	}
	return low
}

// -------------------------------------------------------------------
// 15.5 Prefix Sum (companion: algorithms/005-prefix-sum.go)
// -------------------------------------------------------------------

// countSubarraysWithTargetSumUsingPrefixSums counts contiguous subarrays whose sum
// equals target, including arrays with negative values. If
// currentPrefix-previousPrefix=target, a prior prefix of currentPrefix-target starts a
// valid subarray. seen[0]=1 represents the empty prefix. Time O(n); space O(n).
func countSubarraysWithTargetSumUsingPrefixSums(nums []int, target int) int {
	seen := map[int]int{0: 1}
	prefix, answer := 0, 0
	for _, value := range nums {
		prefix += value
		answer += seen[prefix-target]
		seen[prefix]++
	}
	return answer
}

// -------------------------------------------------------------------
// 15.6 Breadth-First Search (companion: algorithms/007-bfs.go)
// -------------------------------------------------------------------

// shortestPathLengthUnweightedBreadthFirstSearch returns the fewest edges from start to
// target, or -1 if unreachable. Breadth-first search explores vertices by
// increasing distance, and marking on enqueue prevents duplicate work. For V
// vertices and E edges, time O(V+E); space O(V).
func shortestPathLengthUnweightedBreadthFirstSearch(graph map[int][]int, start, target int) int {
	type state struct {
		node     int
		distance int
	}

	queue := []state{{node: start}}
	head := 0
	seen := map[int]struct{}{start: {}}

	for head < len(queue) {
		current := queue[head]
		head++
		if current.node == target {
			return current.distance
		}
		for _, neighbor := range graph[current.node] {
			if _, ok := seen[neighbor]; ok {
				continue
			}
			seen[neighbor] = struct{}{} // Mark on enqueue.
			queue = append(queue, state{
				node:     neighbor,
				distance: current.distance + 1,
			})
		}
	}
	return -1
}

var fourWayGridDirections = [][2]int{
	{1, 0},
	{-1, 0},
	{0, 1},
	{0, -1},
}

// -------------------------------------------------------------------
// 15.7 Depth-First Search (companion: algorithms/008-dfs-and-backtracking.go)
// -------------------------------------------------------------------

// iterativeDepthFirstVisitOrder returns node IDs in depth-first visit order from
// start; it does not compute shortest paths or disconnected components. Marking
// when pushed prevents duplicates. Reversed insertion preserves neighbor order.
func iterativeDepthFirstVisitOrder(graph map[int][]int, start int) []int {
	visited := map[int]bool{start: true}
	stack := []int{start}
	order := make([]int, 0, len(graph))
	for len(stack) > 0 {
		last := len(stack) - 1
		node := stack[last]
		stack = stack[:last]
		order = append(order, node)
		neighbors := graph[node]
		for index := len(neighbors) - 1; index >= 0; index-- {
			neighbor := neighbors[index]
			if !visited[neighbor] {
				visited[neighbor] = true
				stack = append(stack, neighbor)
			}
		}
	}
	return order
}

// countIslandsUsingDepthFirstSearch counts four-directionally connected groups of ASCII
// byte '1'. Each depth-first search changes visited land to '0', so this function
// mutates grid. Time O(rows*cols); recursion space can reach O(rows*cols).
func countIslandsUsingDepthFirstSearch(grid [][]byte) int {
	// Interview grids are normally rectangular.
	if len(grid) == 0 {
		return 0
	}
	rows, cols := len(grid), len(grid[0])

	var visitConnectedLand func(int, int)
	visitConnectedLand = func(row, col int) {
		if row < 0 || row >= rows || col < 0 || col >= cols {
			return
		}
		if grid[row][col] != '1' {
			return
		}
		grid[row][col] = '0'
		for _, direction := range fourWayGridDirections {
			visitConnectedLand(row+direction[0], col+direction[1])
		}
	}

	count := 0
	for row := 0; row < rows; row++ {
		for col := 0; col < cols; col++ {
			if grid[row][col] == '1' {
				count++
				visitConnectedLand(row, col)
			}
		}
	}
	return count
}

// -------------------------------------------------------------------
// 15.8 Backtracking (companion: algorithms/008-dfs-and-backtracking.go)
// -------------------------------------------------------------------

// allSubsetsUsingBacktracking returns the power set, including the empty subset. The
// path holds the current choices; each recursive call chooses a later index, and
// slices.Clone saves a snapshot before path is changed again. Duplicate input values
// produce duplicate subsets. Time/output O(n*2^n).
// Requires: import "slices"
func allSubsetsUsingBacktracking(nums []int) [][]int {
	answer := make([][]int, 0, 1<<len(nums))
	path := make([]int, 0, len(nums))

	var backtrack func(int)
	backtrack = func(start int) {
		answer = append(answer, slices.Clone(path))
		for index := start; index < len(nums); index++ {
			path = append(path, nums[index])
			backtrack(index + 1)
			path = path[:len(path)-1]
		}
	}

	backtrack(0)
	return answer
}

// -------------------------------------------------------------------
// 15.9 Monotonic Stack (companion: algorithms/009-stack-and-monotonic-stack.go)
// -------------------------------------------------------------------

// nextGreaterElementIndexUsingMonotonicStack returns, for every position, the index of
// the first strictly larger value to its right, or -1. The stack stores unresolved
// indices whose values are non-increasing. Each index is pushed and popped once: time
// O(n), space O(n).
func nextGreaterElementIndexUsingMonotonicStack(nums []int) []int {
	answer := make([]int, len(nums))
	for index := range answer {
		answer[index] = -1
	}

	stack := make([]int, 0) // Indices; values decrease.
	for index, value := range nums {
		for len(stack) > 0 && nums[stack[len(stack)-1]] < value {
			top := stack[len(stack)-1]
			stack = stack[:len(stack)-1]
			answer[top] = index
		}
		stack = append(stack, index)
	}
	return answer
}

// -------------------------------------------------------------------
// 15.10 Intervals (companion: algorithms/011-intervals.go)
// -------------------------------------------------------------------

// mergeIntervals sorts intervals by start, then combines each overlap with the last
// output interval. This version treats touching closed intervals as overlapping because
// next.start <= previous.end. Time O(n log n); output space O(n).
// Requires: import "sort"
func mergeIntervals(intervals []Interval) []Interval {
	sort.Slice(intervals, func(i, j int) bool {
		return intervals[i].start < intervals[j].start
	})

	merged := make([]Interval, 0, len(intervals))
	for _, current := range intervals {
		if len(merged) == 0 ||
			current.start > merged[len(merged)-1].end {
			merged = append(merged, current)
			continue
		}
		last := &merged[len(merged)-1]
		last.end = max(last.end, current.end)
	}
	return merged
}

// -------------------------------------------------------------------
// 15.11 Union-Find (companion: algorithms/013-union-find.go)
// -------------------------------------------------------------------

// DisjointSetUnion, often abbreviated DSU and also called union-find, maintains
// a partition of items into non-overlapping groups. parent identifies each
// group's representative, size guides balanced merging, and components tracks
// how many groups remain.
type DisjointSetUnion struct {
	parent     []int
	size       []int
	components int
}

// newDisjointSetUnion creates n separate groups. A disjoint-set union structure tracks
// which items belong to the same connected component without storing every member
// together.
func newDisjointSetUnion(n int) *DisjointSetUnion {
	parent := make([]int, n)
	size := make([]int, n)
	for index := 0; index < n; index++ {
		parent[index] = index
		size[index] = 1
	}
	return &DisjointSetUnion{parent: parent, size: size, components: n}
}

// findRepresentative returns the root identifying x's group. Path compression rewires
// visited nodes directly to the root, making later operations nearly constant time.
func (d *DisjointSetUnion) findRepresentative(x int) int {
	if d.parent[x] != x {
		d.parent[x] = d.findRepresentative(d.parent[x])
	}
	return d.parent[x]
}

// unionSets merges the groups containing a and b and returns true. It returns false
// when they were already connected. Attaching the smaller tree below the larger tree
// limits height; amortized operations are nearly O(1).
func (d *DisjointSetUnion) unionSets(a, b int) bool {
	rootA, rootB := d.findRepresentative(a), d.findRepresentative(b)
	if rootA == rootB {
		return false
	}
	if d.size[rootA] < d.size[rootB] {
		rootA, rootB = rootB, rootA
	}
	d.parent[rootB] = rootA
	d.size[rootA] += d.size[rootB]
	d.components--
	return true
}

// ===================================================================
// 16. Copying, Aliasing, and Mutation
// ===================================================================

// copyAndAliasing contrasts shared slice headers, independent one-dimensional copies,
// shallow matrix copies, deep row copies, and saved backtracking snapshots.
// Requires: import "slices"
func copyAndAliasing(grid [][]int, nums []int) {
	alias := nums // Shared backing array.
	shallow1 := slices.Clone(nums)
	shallow2 := append([]int(nil), nums...)

	matrixShallow := slices.Clone(grid) // Rows still shared.
	matrixCopy := make([][]int, len(grid))
	for r := range grid {
		matrixCopy[r] = slices.Clone(grid[r])
	}

	path := []int{1, 2}
	result := make([][]int, 0)
	result = append(result, slices.Clone(path)) // Save snapshot.

	_ = []any{
		alias, shallow1, shallow2, matrixShallow, matrixCopy, result,
	}
}

// appendCaveat returns the new slice header because append may allocate a different
// backing array.
func appendCaveat(nums []int) []int {
	// The returned slice must be assigned by the caller because append may
	// allocate a new backing array and change the slice header.
	return append(nums, 42)
}

// mutateElements doubles elements through their indices, so aliases sharing the backing
// array observe the writes.
func mutateElements(nums []int) {
	// Element writes are visible through every slice sharing this array.
	for i := range nums {
		nums[i] *= 2
	}
}

// rebindLocally demonstrates that replacing a local slice header does not replace the
// caller's header.
func rebindLocally(nums []int) {
	// This changes only the local slice header, not the caller's header.
	nums = append(nums, 42)
	_ = nums
}

// ===================================================================
// 17. Methods, Interfaces, and Generics
// ===================================================================

type Person struct {
	Name string
	Age  int
}

// label formats a Person value without mutation, demonstrating a value receiver.
// Requires: import "fmt"
func (p Person) label() string {
	return fmt.Sprintf("%s:%d", p.Name, p.Age)
}

// birthday increments a Person age through a pointer receiver so the caller observes
// the change.
func (p *Person) birthday() {
	p.Age++
}

type Stringer interface {
	String() string
}

type Stack[T any] struct {
	data []T
}

// push appends one value to the receiver's stack storage.
func (s *Stack[T]) push(value T) {
	s.data = append(s.data, value)
}

// pop removes and returns the top stack value; false means the stack was empty.
func (s *Stack[T]) pop() (T, bool) {
	var zero T
	if len(s.data) == 0 {
		return zero, false
	}
	index := len(s.data) - 1
	value := s.data[index]
	s.data[index] = zero
	s.data = s.data[:index]
	return value, true
}

type SupportedNumber interface {
	~int | ~int64 | ~float64
}

// sumValues adds values whose type satisfies the SupportedNumber generic constraint.
func sumValues[T SupportedNumber](values []T) T {
	var total T
	for _, value := range values {
		total += value
	}
	return total
}

// cloneMap returns a new map with copied keys and values; referenced values are still
// shallow copies.
func cloneMap[K comparable, V any](source map[K]V) map[K]V {
	result := make(map[K]V, len(source))
	for key, value := range source {
		result[key] = value
	}
	return result
}

// typedNilInterfacePattern demonstrates that an interface containing a typed nil
// pointer is not itself nil.
func typedNilInterfacePattern() bool {
	var node *ListNode
	var value any = node
	return value == nil // false: the interface has dynamic type *ListNode.
}

/*
Struct and interface notes:

- Struct assignment copies fields. Pointer fields still point to shared data.
- A value of type T has methods with receiver T; *T has methods for T and *T.
- Use pointer receivers to mutate or avoid copying a large struct.
- Exported names begin with an uppercase letter.
- A map key must be comparable; slices, maps, and functions are not.
- An interface is nil only when both dynamic type and dynamic value are nil.
  Storing a typed nil pointer in an interface produces a non-nil interface.
- Go has no generic methods with their own type parameters; use a generic
  function or a generic receiver type.
*/

// ===================================================================
// 18. Goroutines, Channels, Context, and Synchronization
// ===================================================================

// squareWorkerPool demonstrates bounded concurrency: workers receive indexed jobs,
// preserve output order through result indices, and stop when context is canceled or
// jobs close. The WaitGroup closes results only after every worker exits.
// Requires: import "context"
// Requires: import "sync"
func squareWorkerPool(ctx context.Context, nums []int, workers int) []int {
	if workers <= 0 {
		return nil
	}

	type job struct {
		index int
		value int
	}
	type result struct {
		index int
		value int
	}

	jobs := make(chan job, len(nums))
	results := make(chan result, len(nums))
	var wg sync.WaitGroup

	worker := func() {
		defer wg.Done()
		for {
			select {
			case <-ctx.Done():
				return
			case current, ok := <-jobs:
				if !ok {
					return
				}
				select {
				case <-ctx.Done():
					return
				case results <- result{
					index: current.index,
					value: current.value * current.value,
				}:
				}
			}
		}
	}

	wg.Add(workers)
	for workerIndex := 0; workerIndex < workers; workerIndex++ {
		go worker()
	}

	go func() {
		defer close(jobs)
		for index, value := range nums {
			select {
			case <-ctx.Done():
				return
			case jobs <- job{index: index, value: value}:
			}
		}
	}()

	go func() {
		wg.Wait()
		close(results)
	}()

	squared := make([]int, len(nums))
	for result := range results {
		squared[result.index] = result.value
	}
	return squared
}

// mutexCounterPattern starts workers that share one counter. The mutex makes each
// read-modify-write increment exclusive; the WaitGroup waits for completion. Without
// the lock, increments race and can be lost.
// Requires: import "sync"
func mutexCounterPattern(workers int) int {
	if workers <= 0 {
		return 0
	}
	var mu sync.Mutex
	var wg sync.WaitGroup
	count := 0

	wg.Add(workers)
	for i := 0; i < workers; i++ {
		go func() {
			defer wg.Done()
			mu.Lock()
			count++
			mu.Unlock()
		}()
	}
	wg.Wait()
	return count
}

// bufferedChannelPattern sends all values into a sufficiently buffered channel, closes
// it from the sending side, and ranges until drained.
func bufferedChannelPattern(values []int) []int {
	channel := make(chan int, len(values))
	for _, value := range values {
		channel <- value
	}
	close(channel)

	result := make([]int, 0, len(values))
	for value := range channel {
		result = append(result, value)
	}
	return result
}

// timeoutPattern derives a context with a deadline and races normal completion against
// cancellation. Always call cancel to release timer resources even when work finishes
// first.
// Requires: import "context"
// Requires: import "time"
func timeoutPattern(parent context.Context) error {
	ctx, cancel := context.WithTimeout(parent, 100*time.Millisecond)
	defer cancel()

	select {
	case <-time.After(10 * time.Millisecond):
		return nil
	case <-ctx.Done():
		return ctx.Err()
	}
}

/*
Concurrency memory rules:

- Start a goroutine only when you know how it stops.
- The sender normally closes a channel; receivers should not.
- Sending to or closing a closed channel panics.
- Receiving from a closed channel returns buffered values, then zero,false.
- A nil channel blocks forever in send/receive cases.
- Run `go test -race ./...` for concurrent production code.
*/

// ===================================================================
// 19. Hash Maps and Counting
// ===================================================================

// groupAnagramsBySortedRunes groups words containing the same runes with the same
// multiplicities. Sorting each word's runes creates a canonical map key: anagrams
// produce identical keys. For maximum word length m, time O(totalWords*m log m).
// Requires via helper: import "slices"
func groupAnagramsBySortedRunes(words []string) [][]string {
	groups := make(map[string][]string)
	for _, word := range words {
		key := sortedRunesKey(word)
		groups[key] = append(groups[key], word)
	}

	answer := make([][]string, 0, len(groups))
	for _, group := range groups {
		answer = append(answer, group)
	}
	return answer
}

// longestConsecutiveSequenceLength returns the longest run of consecutive integers in
// any input order. It starts counting only at values whose predecessor is absent, so
// each stored value participates in one run. Expected time O(n); space O(n).
func longestConsecutiveSequenceLength(nums []int) int {
	values := make(map[int]struct{}, len(nums))
	for _, value := range nums {
		values[value] = struct{}{}
	}
	best := 0
	for value := range values {
		if _, exists := values[value-1]; exists {
			continue
		}
		end := value
		for {
			if _, exists := values[end]; !exists {
				break
			}
			end++
		}
		best = max(best, end-value)
	}
	return best
}

// topKFrequentValuesUsingBuckets returns k values with highest frequencies. A value
// occurring f times is placed in bucket f; scanning buckets from high to low avoids
// sorting all distinct values. Tie order is unspecified. Time O(n); space O(n).
func topKFrequentValuesUsingBuckets(nums []int, k int) []int {
	if k <= 0 {
		return nil
	}

	frequency := make(map[int]int)
	for _, value := range nums {
		frequency[value]++
	}

	buckets := make([][]int, len(nums)+1)
	for value, count := range frequency {
		buckets[count] = append(buckets[count], value)
	}

	answer := make([]int, 0, min(k, len(frequency)))
	for count := len(buckets) - 1; count > 0 && len(answer) < k; count-- {
		for _, value := range buckets[count] {
			answer = append(answer, value)
			if len(answer) == k {
				break
			}
		}
	}
	return answer // Ties may appear in any order.
}

// ===================================================================
// 20. Two Pointers, Palindromes, and Linked Lists
// ===================================================================

// uniqueTripletsSummingToZero returns unique value triples whose sum is zero. Sorting enables a fixed
// first value plus inward-moving pointers; skipping equal values prevents duplicate
// triples. It mutates nums. Time O(n^2); output excluded from space O(1).
// Requires: import "slices"
func uniqueTripletsSummingToZero(nums []int) [][]int {
	slices.Sort(nums)
	answer := make([][]int, 0)

	for index, value := range nums {
		if index > 0 && value == nums[index-1] {
			continue
		}
		left, right := index+1, len(nums)-1
		for left < right {
			total := value + nums[left] + nums[right]
			switch {
			case total == 0:
				answer = append(
					answer,
					[]int{value, nums[left], nums[right]},
				)
				left++
				right--
				for left < right && nums[left] == nums[left-1] {
					left++
				}
				for left < right && nums[right] == nums[right+1] {
					right--
				}
			case total < 0:
				left++
			default:
				right--
			}
		}
	}
	return answer
}

// moveZeroes moves zero values to the end in place while preserving non-zero order.
// Time O(n); space O(1).
func moveZeroes(nums []int) {
	write := 0
	for read, value := range nums {
		if value != 0 {
			nums[write], nums[read] = nums[read], nums[write]
			write++
		}
	}
}

// maximumWaterContainerAreaUsingTwoPointers solves “Container With Most Water.” Width
// shrinks every step, so only moving the shorter wall can possibly increase the
// limiting height. Time O(n); space O(1).
func maximumWaterContainerAreaUsingTwoPointers(height []int) int {
	left, right, best := 0, len(height)-1, 0
	for left < right {
		best = max(
			best,
			(right-left)*min(height[left], height[right]),
		)
		if height[left] < height[right] {
			left++
		} else {
			right--
		}
	}
	return best
}

// countPalindromicSubstringsByExpandingCenters counts every palindromic substring. Each
// character and each gap is a center; matching characters expand outward until they
// differ. Time O(n^2); space O(1).
func countPalindromicSubstringsByExpandingCenters(s string) int {
	expand := func(left, right int) int {
		count := 0
		for left >= 0 && right < len(s) && s[left] == s[right] {
			count++
			left--
			right++
		}
		return count
	}

	count := 0
	for center := 0; center < len(s); center++ {
		count += expand(center, center)
		count += expand(center, center+1)
	}
	return count
}

// isPalindromeIgnoringNonLettersAndDigits compares Unicode letters and digits
// case-insensitively while skipping punctuation and spaces. Time O(number of runes);
// rune-copy space O(number of runes).
// Requires: import "unicode"
func isPalindromeIgnoringNonLettersAndDigits(s string) bool {
	runes := []rune(s)
	left, right := 0, len(runes)-1
	for left < right {
		for left < right && !unicode.IsLetter(runes[left]) &&
			!unicode.IsDigit(runes[left]) {
			left++
		}
		for left < right && !unicode.IsLetter(runes[right]) &&
			!unicode.IsDigit(runes[right]) {
			right--
		}
		if unicode.ToLower(runes[left]) != unicode.ToLower(runes[right]) {
			return false
		}
		left++
		right--
	}
	return true
}

// mergeTwoLists reuses nodes from two ascending linked lists to produce one ascending
// list. Time O(a+b); space O(1).
func mergeTwoLists(a, b *ListNode) *ListNode {
	dummy := &ListNode{}
	tail := dummy
	for a != nil && b != nil {
		if a.Val <= b.Val {
			tail.Next, a = a, a.Next
		} else {
			tail.Next, b = b, b.Next
		}
		tail = tail.Next
	}
	if a != nil {
		tail.Next = a
	} else {
		tail.Next = b
	}
	return dummy.Next
}

// reverseList reverses a singly linked list in place by redirecting each Next pointer.
// Time O(n); space O(1).
func reverseList(head *ListNode) *ListNode {
	var previous *ListNode
	for head != nil {
		next := head.Next
		head.Next = previous
		previous = head
		head = next
	}
	return previous
}

// linkedListHasCycleUsingFloydAlgorithm uses Floyd's tortoise-and-hare method: one
// pointer advances one node and the other two. In a cycle the faster pointer must
// eventually meet the slower one; at a nil link no cycle exists. Time O(n); space O(1).
func linkedListHasCycleUsingFloydAlgorithm(head *ListNode) bool {
	slow, fast := head, head
	for fast != nil && fast.Next != nil {
		slow = slow.Next
		fast = fast.Next.Next
		if slow == fast {
			return true
		}
	}
	return false
}

// removeNthLinkedListNodeFromEnd keeps fast n nodes ahead of slow. When fast reaches
// the tail, slow is immediately before the node to remove. A dummy node handles removal
// of the original head. Time O(n); space O(1).
func removeNthLinkedListNodeFromEnd(head *ListNode, n int) *ListNode {
	if n <= 0 {
		return head
	}

	dummy := &ListNode{Next: head}
	fast, slow := dummy, dummy
	for step := 0; step < n; step++ {
		fast = fast.Next
		if fast == nil {
			return head
		}
	}
	for fast.Next != nil {
		fast = fast.Next
		slow = slow.Next
	}
	slow.Next = slow.Next.Next
	return dummy.Next
}

// ===================================================================
// 21. Sliding Window Variants
// ===================================================================

// longestSubstringWithoutRepeatedASCIIBytes returns the longest substring containing no
// repeated bytes. It is intentionally ASCII-oriented; arbitrary Unicode text needs
// rune-based indexing. The set always equals bytes in the current window. Time O(n);
// space O(alphabet).
func longestSubstringWithoutRepeatedASCIIBytes(s string) int {
	// Byte-oriented version, appropriate when the problem guarantees ASCII.
	seen := make(map[byte]struct{})
	left, best := 0, 0
	for right := 0; right < len(s); right++ {
		for {
			if _, ok := seen[s[right]]; !ok {
				break
			}
			delete(seen, s[left])
			left++
		}
		seen[s[right]] = struct{}{}
		best = max(best, right-left+1)
	}
	return best
}

// minimumSubarrayLengthWithSumAtLeastTarget requires non-negative values so removing
// from the left can only decrease the sum. It returns 0 when no qualifying contiguous
// subarray exists. Time O(n); space O(1).
func minimumSubarrayLengthWithSumAtLeastTarget(nums []int, target int) int {
	left, total := 0, 0
	best := len(nums) + 1
	for right, value := range nums {
		total += value
		for total >= target {
			best = min(best, right-left+1)
			total -= nums[left]
			left++
		}
	}
	if best == len(nums)+1 {
		return 0
	}
	return best
}

// maximumSumFixedLengthWindow returns the largest sum among contiguous windows of
// exactly k elements, or 0 for invalid k. Add the entering value and remove the leaving
// value to update each window in O(1). Total time O(n).
func maximumSumFixedLengthWindow(nums []int, k int) int {
	if k <= 0 || k > len(nums) {
		return 0
	}
	window := 0
	for _, value := range nums[:k] {
		window += value
	}
	best := window
	for right := k; right < len(nums); right++ {
		window += nums[right] - nums[right-k]
		best = max(best, window)
	}
	return best
}

// countSubarraysWithExactlyKDistinctValues uses: exactly(k) = atMost(k) - atMost(k-1).
// Every subarray with exactly k distinct values appears in the first count and not the
// second. Time O(n); space O(k).
func countSubarraysWithExactlyKDistinctValues(nums []int, k int) int {
	return countSubarraysWithAtMostKDistinctValues(nums, k) -
		countSubarraysWithAtMostKDistinctValues(nums, k-1)
}

// ===================================================================
// 22. Binary Search Variants
// ===================================================================

// searchRotatedSortedArray finds target in an ascending array rotated at an unknown
// pivot. At least one half around middle is still sorted; range checks decide which
// half can contain target. Returns -1 if absent. Time O(log n), assuming distinct
// values.
func searchRotatedSortedArray(nums []int, target int) int {
	left, right := 0, len(nums)-1
	for left <= right {
		middle := left + (right-left)/2
		if nums[middle] == target {
			return middle
		}
		if nums[left] <= nums[middle] {
			if nums[left] <= target && target < nums[middle] {
				right = middle - 1
			} else {
				left = middle + 1
			}
		} else if nums[middle] < target && target <= nums[right] {
			left = middle + 1
		} else {
			right = middle - 1
		}
	}
	return -1
}

// medianOfTwoSortedArraysUsingPartition binary-searches a cut in the shorter array and
// derives the matching cut in the other. A valid partition has every left value <=
// every right value and places half the combined elements on the left. Time O(log
// min(m,n)); space O(1).
func medianOfTwoSortedArraysUsingPartition(a, b []int) float64 {
	if len(a) > len(b) {
		return medianOfTwoSortedArraysUsingPartition(b, a)
	}
	if len(a)+len(b) == 0 {
		panic("at least one input must be non-empty")
	}

	maxInt := int(^uint(0) >> 1)
	minInt := -maxInt - 1
	m, n := len(a), len(b)
	half := (m + n + 1) / 2
	left, right := 0, m

	for left <= right {
		aCut := left + (right-left)/2
		bCut := half - aCut

		aLeft, aRight := minInt, maxInt
		bLeft, bRight := minInt, maxInt
		if aCut > 0 {
			aLeft = a[aCut-1]
		}
		if aCut < m {
			aRight = a[aCut]
		}
		if bCut > 0 {
			bLeft = b[bCut-1]
		}
		if bCut < n {
			bRight = b[bCut]
		}

		if aLeft <= bRight && bLeft <= aRight {
			if (m+n)%2 == 1 {
				return float64(max(aLeft, bLeft))
			}
			leftMax := float64(max(aLeft, bLeft))
			rightMin := float64(min(aRight, bRight))
			return (leftMax + rightMin) / 2
		}
		if aLeft > bRight {
			right = aCut - 1
		} else {
			left = aCut + 1
		}
	}
	panic("inputs must be sorted")
}

// ===================================================================
// 23. Prefix Sums and Difference Arrays
// ===================================================================

// OneDimensionalPrefixSum stores cumulative sums for constant-time range queries.
type OneDimensionalPrefixSum struct {
	prefix []int
}

// newOneDimensionalPrefixSum stores prefix[i] as the sum of values before index i. The
// leading zero makes an inclusive range [left,right] equal
// prefix[right+1]-prefix[left]. Build time/space O(n).
func newOneDimensionalPrefixSum(nums []int) OneDimensionalPrefixSum {
	prefix := make([]int, len(nums)+1)
	for index, value := range nums {
		prefix[index+1] = prefix[index] + value
	}
	return OneDimensionalPrefixSum{prefix: prefix}
}

// sumRange returns the inclusive one-dimensional range sum [left,right] in O(1).
// Indices must be valid for the original input.
func (p OneDimensionalPrefixSum) sumRange(left, right int) int {
	return p.prefix[right+1] - p.prefix[left]
}

// TwoDimensionalPrefixSum stores cumulative rectangle sums.
type TwoDimensionalPrefixSum struct {
	prefix [][]int
}

// newTwoDimensionalPrefixSum builds a table with one zero border. prefix[r+1][c+1] is
// the sum of the rectangle from (0,0) through (r,c). Build time/space O(rows*cols).
func newTwoDimensionalPrefixSum(matrix [][]int) TwoDimensionalPrefixSum {
	rows := len(matrix)
	cols := 0
	if rows > 0 {
		cols = len(matrix[0])
	}

	prefix := make([][]int, rows+1)
	for row := range prefix {
		prefix[row] = make([]int, cols+1)
	}
	for row := 0; row < rows; row++ {
		for col := 0; col < cols; col++ {
			prefix[row+1][col+1] = matrix[row][col] +
				prefix[row][col+1] +
				prefix[row+1][col] -
				prefix[row][col]
		}
	}
	return TwoDimensionalPrefixSum{prefix: prefix}
}

// sumRegion returns an inclusive rectangle sum using inclusion-exclusion: whole prefix
// minus the two outside strips plus their twice-subtracted overlap. Query time O(1).
func (p TwoDimensionalPrefixSum) sumRegion(r1, c1, r2, c2 int) int {
	return p.prefix[r2+1][c2+1] -
		p.prefix[r1][c2+1] -
		p.prefix[r2+1][c1] +
		p.prefix[r1][c1]
}

// applyRangeAdditionsUsingDifferenceArray applies inclusive updates [left,right,delta]
// without touching every covered element. +delta marks where an effect starts and
// -delta after right marks where it stops; one prefix scan materializes values. Time
// O(length+updates).
func applyRangeAdditionsUsingDifferenceArray(length int, updates [][3]int) []int {
	if length <= 0 {
		return nil
	}
	difference := make([]int, length+1)
	for _, update := range updates {
		left, right, delta := update[0], update[1], update[2]
		if left < 0 || left >= length || right < left || right >= length {
			continue
		}
		difference[left] += delta
		difference[right+1] -= delta
	}

	result := make([]int, length)
	running := 0
	for index := range result {
		running += difference[index]
		result[index] = running
	}
	return result
}

// ===================================================================
// 24. Breadth-First Search, Topological Sort, and Shortest Paths
// ===================================================================

// binaryTreeValuesByLevelBreadthFirst returns one value slice per tree depth. The queue
// segment present at the start of an outer iteration is exactly one level. Time
// O(nodes); space O(maximum tree width).
func binaryTreeValuesByLevelBreadthFirst(root *TreeNode) [][]int {
	if root == nil {
		return nil
	}

	answer := make([][]int, 0)
	queue := []*TreeNode{root}
	head := 0

	for head < len(queue) {
		levelSize := len(queue) - head
		level := make([]int, 0, levelSize)
		for levelIndex := 0; levelIndex < levelSize; levelIndex++ {
			node := queue[head]
			head++
			level = append(level, node.Val)
			if node.Left != nil {
				queue = append(queue, node.Left)
			}
			if node.Right != nil {
				queue = append(queue, node.Right)
			}
		}
		answer = append(answer, level)
	}
	return answer
}

// topologicalOrderUsingKahnAlgorithm orders a directed graph where each edge is
// [prerequisite,course]. Kahn's algorithm repeatedly removes zero-indegree
// nodes; if fewer than n are removed, a directed cycle exists and nil is
// returned. For V vertices and E edges, time O(V+E).
func topologicalOrderUsingKahnAlgorithm(n int, edges [][2]int) []int {
	graph := make([][]int, n)
	indegree := make([]int, n)
	for _, edge := range edges {
		prerequisite, course := edge[0], edge[1]
		graph[prerequisite] = append(graph[prerequisite], course)
		indegree[course]++
	}

	queue := make([]int, 0, n)
	for node, degree := range indegree {
		if degree == 0 {
			queue = append(queue, node)
		}
	}

	order := make([]int, 0, n)
	for head := 0; head < len(queue); head++ {
		node := queue[head]
		order = append(order, node)
		for _, neighbor := range graph[node] {
			indegree[neighbor]--
			if indegree[neighbor] == 0 {
				queue = append(queue, neighbor)
			}
		}
	}
	if len(order) != n {
		return nil
	}
	return order
}

type WeightedEdge struct {
	to     int
	weight int
}

type DistanceState struct {
	distance int
	node     int
}

// DistanceMinHeap orders graph states by their currently known distance.
type DistanceMinHeap []DistanceState

// Len reports the number of elements required by heap.Interface.
func (h DistanceMinHeap) Len() int { return len(h) }

// Less defines which of two elements has higher heap priority.
func (h DistanceMinHeap) Less(i, j int) bool {
	return h[i].distance < h[j].distance
}

// Swap exchanges two heap positions while container/heap restores its invariant.
func (h DistanceMinHeap) Swap(i, j int) {
	h[i], h[j] = h[j], h[i]
}

// Push appends a concrete value received through heap.Interface's any parameter.
func (h *DistanceMinHeap) Push(value any) {
	*h = append(*h, value.(DistanceState))
}

// Pop removes the final slice item after container/heap has moved the root there.
func (h *DistanceMinHeap) Pop() any {
	old := *h
	value := old[len(old)-1]
	*h = old[:len(old)-1]
	return value
}

// shortestDistancesUsingDijkstraAlgorithm returns minimum distances from start in a
// graph with non-negative edge weights. The min-heap chooses the unsettled
// shortest candidate; stale entries are skipped instead of decreased in place.
// For V vertices and E edges, time O((V+E) log V).
// Requires: import "container/heap"
func shortestDistancesUsingDijkstraAlgorithm(graph map[int][]WeightedEdge, start int) map[int]int {
	distance := map[int]int{start: 0}
	priorityQueue := &DistanceMinHeap{{distance: 0, node: start}}
	heap.Init(priorityQueue)

	for priorityQueue.Len() > 0 {
		current := heap.Pop(priorityQueue).(DistanceState)
		if current.distance != distance[current.node] {
			continue // Stale heap entry.
		}
		for _, edge := range graph[current.node] {
			nextDistance := current.distance + edge.weight
			oldDistance, seen := distance[edge.to]
			if !seen || nextDistance < oldDistance {
				distance[edge.to] = nextDistance
				heap.Push(priorityQueue, DistanceState{
					distance: nextDistance,
					node:     edge.to,
				})
			}
		}
	}
	return distance
}

// gridShortestDistancesUsingBreadthFirstSearch treats 0 cells as open and non-zero
// cells as blocked. It returns shortest four-way distances from start, with -1 for
// unreachable cells. Time/space O(rows*cols).
func gridShortestDistancesUsingBreadthFirstSearch(grid [][]int, start Point) [][]int {
	if len(grid) == 0 || len(grid[0]) == 0 {
		return nil
	}

	rows, cols := len(grid), len(grid[0])
	distance := make([][]int, rows)
	for row := range distance {
		distance[row] = make([]int, cols)
		for col := range distance[row] {
			distance[row][col] = -1
		}
	}
	if start.Row < 0 || start.Row >= rows ||
		start.Col < 0 || start.Col >= cols ||
		grid[start.Row][start.Col] != 0 {
		return distance
	}

	queue := []Point{start}
	distance[start.Row][start.Col] = 0
	for head := 0; head < len(queue); head++ {
		current := queue[head]
		for _, direction := range fourWayGridDirections {
			next := Point{
				Row: current.Row + direction[0],
				Col: current.Col + direction[1],
			}
			if next.Row < 0 || next.Row >= rows ||
				next.Col < 0 || next.Col >= cols ||
				grid[next.Row][next.Col] != 0 ||
				distance[next.Row][next.Col] != -1 {
				continue
			}
			distance[next.Row][next.Col] =
				distance[current.Row][current.Col] + 1
			queue = append(queue, next) // Marked before enqueue, so no duplicates.
		}
	}
	return distance
}

// gridDistancesFromMultipleSources enqueues every valid source at distance zero before
// breadth-first search. The first visit to a cell is therefore its distance to the
// nearest source. Blocked cells are non-zero; unreachable cells stay -1.
func gridDistancesFromMultipleSources(grid [][]int, sources []Point) [][]int {
	if len(grid) == 0 || len(grid[0]) == 0 {
		return nil
	}
	rows, cols := len(grid), len(grid[0])
	distance := make([][]int, rows)
	for row := range distance {
		distance[row] = make([]int, cols)
		for col := range distance[row] {
			distance[row][col] = -1
		}
	}

	queue := make([]Point, 0, len(sources))
	for _, source := range sources {
		if source.Row < 0 || source.Row >= rows ||
			source.Col < 0 || source.Col >= cols ||
			grid[source.Row][source.Col] != 0 ||
			distance[source.Row][source.Col] != -1 {
			continue
		}
		distance[source.Row][source.Col] = 0
		queue = append(queue, source)
	}

	for head := 0; head < len(queue); head++ {
		current := queue[head]
		for _, direction := range fourWayGridDirections {
			next := Point{
				Row: current.Row + direction[0],
				Col: current.Col + direction[1],
			}
			if next.Row < 0 || next.Row >= rows ||
				next.Col < 0 || next.Col >= cols ||
				grid[next.Row][next.Col] != 0 ||
				distance[next.Row][next.Col] != -1 {
				continue
			}
			distance[next.Row][next.Col] =
				distance[current.Row][current.Col] + 1
			queue = append(queue, next)
		}
	}
	return distance
}

// orientUndirectedTreeFromRoot converts undirected edges into parent-to-children
// adjacency lists relative to root. Carrying the parent avoids walking immediately back
// along an edge. Input must be a valid tree. Time O(n).
func orientUndirectedTreeFromRoot(n int, edges [][2]int, root int) [][]int {
	graph := make([][]int, n)
	for _, edge := range edges {
		a, b := edge[0], edge[1]
		graph[a] = append(graph[a], b)
		graph[b] = append(graph[b], a)
	}
	children := make([][]int, n)
	type state struct {
		node   int
		parent int
	}
	stack := []state{{node: root, parent: -1}}
	for len(stack) > 0 {
		current := stack[len(stack)-1]
		stack = stack[:len(stack)-1]
		for _, neighbor := range graph[current.node] {
			if neighbor == current.parent {
				continue
			}
			children[current.node] = append(children[current.node], neighbor)
			stack = append(stack, state{node: neighbor, parent: current.node})
		}
	}
	return children
}

// ===================================================================
// 25. Depth-First Search and Backtracking Variants
// ===================================================================

// allPermutationsUsingBacktracking returns every ordering of nums. used[index] records
// which positions are already in the current path; choose, recurse, and unchoose
// restores the invariant. Time/output O(n*n!).
// Requires: import "slices"
func allPermutationsUsingBacktracking(nums []int) [][]int {
	answer := make([][]int, 0)
	path := make([]int, 0, len(nums))
	used := make([]bool, len(nums))

	var backtrack func()
	backtrack = func() {
		if len(path) == len(nums) {
			answer = append(answer, slices.Clone(path))
			return
		}
		for index, value := range nums {
			if used[index] {
				continue
			}
			used[index] = true
			path = append(path, value)
			backtrack()
			path = path[:len(path)-1]
			used[index] = false
		}
	}

	backtrack()
	return answer
}

// combinationsSummingToTargetWithReuse returns combinations totaling target where each positive candidate may
// be reused. Sorting permits early stopping; recursing with the same index allows
// reuse, while start prevents reordered duplicates. It mutates candidates.
// Requires: import "slices"
func combinationsSummingToTargetWithReuse(candidates []int, target int) [][]int {
	slices.Sort(candidates)
	answer := make([][]int, 0)
	path := make([]int, 0)

	var backtrack func(int, int)
	backtrack = func(start, remaining int) {
		if remaining == 0 {
			answer = append(answer, slices.Clone(path))
			return
		}
		for index := start; index < len(candidates); index++ {
			value := candidates[index]
			if value > remaining {
				break
			}
			path = append(path, value)
			backtrack(index, remaining-value)
			path = path[:len(path)-1]
		}
	}

	backtrack(0, target)
	return answer
}

// ===================================================================
// 26. Stacks and Monotonic Stacks
// ===================================================================

// hasValidBracketNesting returns whether (), [], and {} are properly nested; unrelated
// bytes are ignored. Time O(n); space O(n).
func hasValidBracketNesting(s string) bool {
	closeToOpen := map[byte]byte{
		')': '(',
		']': '[',
		'}': '{',
	}
	stack := make([]byte, 0, len(s))
	for index := 0; index < len(s); index++ {
		char := s[index]
		if char == '(' || char == '[' || char == '{' {
			stack = append(stack, char)
			continue
		}
		if expected, ok := closeToOpen[char]; ok {
			if len(stack) == 0 || stack[len(stack)-1] != expected {
				return false
			}
			stack = stack[:len(stack)-1]
		}
	}
	return len(stack) == 0
}

// StackWithMinimum stores each value beside the minimum at that depth, allowing
// push, pop, and minimum queries in O(1).
type StackWithMinimum struct {
	stack [][2]int // value, minimum through this position
}

// push appends one value to the receiver's stack storage.
func (s *StackWithMinimum) push(value int) {
	currentMin := value
	if len(s.stack) > 0 {
		currentMin = min(currentMin, s.stack[len(s.stack)-1][1])
	}
	s.stack = append(s.stack, [2]int{value, currentMin})
}

// pop removes and returns the top stack value; false means the stack was empty.
func (s *StackWithMinimum) pop() (int, bool) {
	if len(s.stack) == 0 {
		return 0, false
	}
	top := s.stack[len(s.stack)-1]
	s.stack = s.stack[:len(s.stack)-1]
	return top[0], true
}

// minimum returns the current stack minimum in O(1); false means the stack is empty.
func (s *StackWithMinimum) minimum() (int, bool) {
	if len(s.stack) == 0 {
		return 0, false
	}
	return s.stack[len(s.stack)-1][1], true
}

// daysUntilWarmerTemperature returns how many later positions must pass before a
// strictly warmer value, or 0 if none. The stack stores unresolved indices with
// non-increasing temperatures. Time O(n); space O(n).
func daysUntilWarmerTemperature(temperatures []int) []int {
	answer := make([]int, len(temperatures))
	stack := make([]int, 0, len(temperatures))
	for index, temperature := range temperatures {
		for len(stack) > 0 &&
			temperatures[stack[len(stack)-1]] < temperature {
			previous := stack[len(stack)-1]
			stack = stack[:len(stack)-1]
			answer[previous] = index - previous
		}
		stack = append(stack, index)
	}
	return answer
}

// ===================================================================
// 27. Heap Applications
// ===================================================================

// SortedArrayCursor identifies one current value and where its successor lives.
type SortedArrayCursor struct {
	value      int
	arrayIndex int
	valueIndex int
}

// SortedArrayCursorMinHeap exposes the smallest current value across all arrays.
type SortedArrayCursorMinHeap []SortedArrayCursor

// Len reports the number of elements required by heap.Interface.
func (h SortedArrayCursorMinHeap) Len() int { return len(h) }

// Less defines which of two elements has higher heap priority.
func (h SortedArrayCursorMinHeap) Less(i, j int) bool { return h[i].value < h[j].value }

// Swap exchanges two heap positions while container/heap restores its invariant.
func (h SortedArrayCursorMinHeap) Swap(i, j int) { h[i], h[j] = h[j], h[i] }

// Push appends a concrete value received through heap.Interface's any parameter.
func (h *SortedArrayCursorMinHeap) Push(value any) {
	*h = append(*h, value.(SortedArrayCursor))
}

// Pop removes the final slice item after container/heap has moved the root there.
func (h *SortedArrayCursorMinHeap) Pop() any {
	old := *h
	value := old[len(old)-1]
	*h = old[:len(old)-1]
	return value
}

// mergeSortedArraysUsingMinHeap performs a k-way merge. The min-heap stores the next
// unused value from each sorted input; after removing one cursor, its successor from
// the same array is inserted. Time O(totalValues log k); space O(k).
// Requires: import "container/heap"
func mergeSortedArraysUsingMinHeap(arrays [][]int) []int {
	priorityQueue := &SortedArrayCursorMinHeap{}
	totalLength := 0
	for arrayIndex, values := range arrays {
		totalLength += len(values)
		if len(values) > 0 {
			heap.Push(priorityQueue, SortedArrayCursor{
				value:      values[0],
				arrayIndex: arrayIndex,
			})
		}
	}

	answer := make([]int, 0, totalLength)
	for priorityQueue.Len() > 0 {
		current := heap.Pop(priorityQueue).(SortedArrayCursor)
		answer = append(answer, current.value)
		nextIndex := current.valueIndex + 1
		values := arrays[current.arrayIndex]
		if nextIndex < len(values) {
			heap.Push(priorityQueue, SortedArrayCursor{
				value:      values[nextIndex],
				arrayIndex: current.arrayIndex,
				valueIndex: nextIndex,
			})
		}
	}
	return answer
}

// ===================================================================
// 28. Interval Variants
// ===================================================================

// maximumConcurrentMeetingsUsingTwoPointers returns the most simultaneously active
// half-open intervals [start,end). Sorted starts add a room; an end at the same time
// frees a room before that start. Time O(n log n); space O(n).
// Requires: import "slices"
func maximumConcurrentMeetingsUsingTwoPointers(intervals []Interval) int {
	if len(intervals) == 0 {
		return 0
	}

	starts := make([]int, 0, len(intervals))
	ends := make([]int, 0, len(intervals))
	for _, interval := range intervals {
		if interval.start >= interval.end {
			continue
		}
		starts = append(starts, interval.start)
		ends = append(ends, interval.end)
	}
	if len(starts) == 0 {
		return 0
	}
	slices.Sort(starts)
	slices.Sort(ends)

	rooms, best := 0, 0
	startIndex, endIndex := 0, 0
	for startIndex < len(starts) {
		if starts[startIndex] < ends[endIndex] {
			rooms++
			best = max(best, rooms)
			startIndex++
		} else {
			rooms--
			endIndex++
		}
	}
	return best
}

// insertInterval assumes non-overlapping closed intervals [start,end] sorted by
// start. Touching at an endpoint counts as overlap. It appends intervals before
// the new one, merges every overlap, then appends the untouched suffix.
// Time O(n); output space O(n).
func insertInterval(
	intervals []Interval,
	newInterval Interval,
) []Interval {
	answer := make([]Interval, 0, len(intervals)+1)
	index := 0
	for index < len(intervals) &&
		intervals[index].end < newInterval.start {
		answer = append(answer, intervals[index])
		index++
	}
	for index < len(intervals) &&
		intervals[index].start <= newInterval.end {
		newInterval.start = min(newInterval.start, intervals[index].start)
		newInterval.end = max(newInterval.end, intervals[index].end)
		index++
	}
	answer = append(answer, newInterval)
	return append(answer, intervals[index:]...)
}

// eraseOverlapIntervals returns the minimum removals needed to make intervals
// non-overlapping. Keeping the interval with the earliest end leaves the most room for
// future intervals, which is the greedy invariant. Time O(n log n).
// Requires: import "sort"
func eraseOverlapIntervals(intervals []Interval) int {
	sort.Slice(intervals, func(i, j int) bool {
		return intervals[i].end < intervals[j].end
	})

	removed, previousEnd := 0, 0
	hasPrevious := false
	for _, interval := range intervals {
		if !hasPrevious || interval.start >= previousEnd {
			previousEnd = interval.end
			hasPrevious = true
		} else {
			removed++
		}
	}
	return removed
}

// maxOverlappingIntervals is a sweep-line algorithm. Start events add one active
// interval and end events remove one; sorting end before start on ties gives half-open
// [start,end) behavior. Time O(n log n).
// Requires: import "cmp"
// Requires: import "slices"
func maxOverlappingIntervals(intervals []Interval) int {
	type event struct {
		time  int
		delta int
	}
	events := make([]event, 0, 2*len(intervals))
	for _, interval := range intervals {
		if interval.start >= interval.end {
			continue
		}
		events = append(events,
			event{time: interval.start, delta: 1},
			event{time: interval.end, delta: -1},
		)
	}
	slices.SortFunc(events, func(a, b event) int {
		if a.time != b.time {
			return cmp.Compare(a.time, b.time)
		}
		return cmp.Compare(a.delta, b.delta) // End before start on ties.
	})

	active, best := 0, 0
	for _, current := range events {
		active += current.delta
		best = max(best, active)
	}
	return best
}

// ===================================================================
// 29. Dynamic Programming
// ===================================================================

// maximumSubarraySumUsingKadaneAlgorithm returns the largest sum of a non-empty
// contiguous subarray, or 0 for empty input. At each position the best ending there
// either starts fresh or extends the previous best ending. Time O(n); space O(1).
func maximumSubarraySumUsingKadaneAlgorithm(nums []int) int {
	if len(nums) == 0 {
		return 0
	}
	best, current := nums[0], nums[0]
	for _, value := range nums[1:] {
		current = max(value, current+value)
		best = max(best, current)
	}
	return best
}

// countWaysToClimbStairsUsingRollingState counts sequences of one- and two-step moves.
// Ways(step)=ways(step-1)+ways(step-2); keeping only those two states reduces
// dynamic-programming space to O(1).
func countWaysToClimbStairsUsingRollingState(n int) int {
	if n <= 2 {
		return n
	}
	previous2, previous1 := 1, 2
	for step := 3; step <= n; step++ {
		previous2, previous1 = previous1, previous1+previous2
	}
	return previous1
}

// longestCommonSubsequence returns the maximum length obtainable by deleting characters
// without reordering either string. Matching characters advance both strings; otherwise
// choose the better one-string advance. Time/space O(len(a)*len(b)).
func longestCommonSubsequence(a, b string) int {
	dp := make([][]int, len(a)+1)
	for index := range dp {
		dp[index] = make([]int, len(b)+1)
	}
	for i := len(a) - 1; i >= 0; i-- {
		for j := len(b) - 1; j >= 0; j-- {
			if a[i] == b[j] {
				dp[i][j] = 1 + dp[i+1][j+1]
			} else {
				dp[i][j] = max(dp[i+1][j], dp[i][j+1])
			}
		}
	}
	return dp[0][0]
}

// canPartitionIntoEqualSumSubsets asks whether values can split into two equal-sum
// groups. It is a 0/1 knapsack: possible[s] means some processed values total s, and
// descending updates prevent reusing one value. Time O(n*target).
func canPartitionIntoEqualSumSubsets(nums []int) bool {
	total := 0
	for _, value := range nums {
		total += value
	}
	if total%2 != 0 {
		return false
	}

	target := total / 2
	possible := make([]bool, target+1)
	possible[0] = true
	for _, value := range nums {
		for current := target; current >= value; current-- {
			possible[current] = possible[current] ||
				possible[current-value]
		}
	}
	return possible[target]
}

// minimumCoinsTopDownDynamicProgramming returns the fewest coins totaling amount, or
// -1. Memoization stores each remaining amount; amount+1 is an impossible sentinel
// larger than any valid answer using positive coin values.
func minimumCoinsTopDownDynamicProgramming(coins []int, amount int) int {
	impossible := amount + 1
	memo := make(map[int]int)

	var dp func(int) int
	dp = func(remaining int) int {
		switch {
		case remaining == 0:
			return 0
		case remaining < 0:
			return impossible
		}
		if cached, ok := memo[remaining]; ok {
			return cached
		}

		best := impossible
		for _, coin := range coins {
			best = min(best, 1+dp(remaining-coin))
		}
		memo[remaining] = best
		return best
	}

	answer := dp(amount)
	if answer >= impossible {
		return -1
	}
	return answer
}

// countGridPathsUsingMemoization counts paths from the top-left to bottom-right using
// only down and right moves. The coordinate pair is a comparable map key, and
// memoization evaluates each cell once. Time/space O(rows*cols).
func countGridPathsUsingMemoization(rows, cols int) int {
	memo := make(map[[2]int]int)
	var count func(int, int) int
	count = func(row, col int) int {
		if row == rows-1 && col == cols-1 {
			return 1
		}
		if row >= rows || col >= cols {
			return 0
		}
		key := [2]int{row, col}
		if cached, ok := memo[key]; ok {
			return cached
		}
		memo[key] = count(row+1, col) + count(row, col+1)
		return memo[key]
	}
	if rows <= 0 || cols <= 0 {
		return 0
	}
	return count(0, 0)
}

// ===================================================================
// 30. Union-Find Applications
// ===================================================================

// countConnectedComponentsUsingDisjointSetUnion starts with n separate vertices and
// unions every undirected edge. The structure's remaining group count is the number of
// connected components. Nearly O(n+edges) amortized.
func countConnectedComponentsUsingDisjointSetUnion(n int, edges [][2]int) int {
	dsu := newDisjointSetUnion(n)
	for _, edge := range edges {
		dsu.unionSets(edge[0], edge[1])
	}
	return dsu.components
}

// findRedundantEdge returns the first undirected edge whose endpoints are already
// connected. Adding that edge would create a cycle. It returns a zero pair when no
// redundant edge exists.
func findRedundantEdge(edges [][2]int) [2]int {
	maxNode := 0
	for _, edge := range edges {
		maxNode = max(maxNode, edge[0], edge[1])
	}
	dsu := newDisjointSetUnion(maxNode + 1)
	for _, edge := range edges {
		if !dsu.unionSets(edge[0], edge[1]) {
			return edge
		}
	}
	return [2]int{}
}

// ===================================================================
// 31. Tries and Tree Construction
// ===================================================================

// TrieNode is one node in a trie (prefix tree); each child edge consumes a rune.
type TrieNode struct {
	children map[rune]*TrieNode
	isWord   bool
}

// Trie stores words by shared prefixes.
type Trie struct {
	root *TrieNode
}

// newTrie creates a trie, also called a prefix tree. Each edge stores one rune, so
// shared word prefixes share nodes.
func newTrie() *Trie {
	return &Trie{
		root: &TrieNode{children: make(map[rune]*TrieNode)},
	}
}

// insert adds one word to the trie, creating missing rune edges.
func (t *Trie) insert(word string) {
	node := t.root
	for _, char := range word {
		if node.children[char] == nil {
			node.children[char] = &TrieNode{
				children: make(map[rune]*TrieNode),
			}
		}
		node = node.children[char]
	}
	node.isWord = true
}

// followPrefixPath follows a complete rune path and returns its terminal node, or nil when the path
// is absent.
func (t *Trie) followPrefixPath(text string) *TrieNode {
	node := t.root
	for _, char := range text {
		node = node.children[char]
		if node == nil {
			return nil
		}
	}
	return node
}

// search returns true only when the complete word was inserted, not merely when it is a
// prefix.
func (t *Trie) search(word string) bool {
	node := t.followPrefixPath(word)
	return node != nil && node.isWord
}

// startsWith returns true when any stored word begins with the supplied prefix.
func (t *Trie) startsWith(prefix string) bool {
	return t.followPrefixPath(prefix) != nil
}

// wildcardSearch returns whether the pattern matches a stored word; '.' matches exactly
// one arbitrary rune. A wildcard branches to every child, so worst-case time can be
// exponential in wildcard count.
func (t *Trie) wildcardSearch(pattern string) bool {
	patternRunes := []rune(pattern)
	var search func(int, *TrieNode) bool
	search = func(index int, node *TrieNode) bool {
		if index == len(patternRunes) {
			return node.isWord
		}
		char := patternRunes[index]
		if char != '.' {
			child := node.children[char]
			return child != nil && search(index+1, child)
		}
		for _, child := range node.children {
			if search(index+1, child) {
				return true
			}
		}
		return false
	}
	return search(0, t.root)
}

// buildBinaryTreeLevelOrder interprets pointer values in breadth-first order; nil
// entries represent missing children.
func buildBinaryTreeLevelOrder(values []*int) *TreeNode {
	if len(values) == 0 || values[0] == nil {
		return nil
	}
	root := &TreeNode{Val: *values[0]}
	queue := []*TreeNode{root}
	index := 1
	for head := 0; head < len(queue) && index < len(values); head++ {
		node := queue[head]
		if index < len(values) && values[index] != nil {
			node.Left = &TreeNode{Val: *values[index]}
			queue = append(queue, node.Left)
		}
		index++
		if index < len(values) && values[index] != nil {
			node.Right = &TreeNode{Val: *values[index]}
			queue = append(queue, node.Right)
		}
		index++
	}
	return root
}

// buildTreePreorderInorder reconstructs a binary tree with unique values. Preorder
// supplies each subtree root; its position in inorder separates left and right subtree
// values. The index map gives O(n) time and O(n) space.
func buildTreePreorderInorder(preorder, inorder []int) *TreeNode {
	if len(preorder) == 0 || len(preorder) != len(inorder) {
		return nil
	}
	inorderIndex := make(map[int]int, len(inorder))
	for index, value := range inorder {
		inorderIndex[value] = index
	}
	preorderIndex := 0
	var build func(int, int) *TreeNode
	build = func(left, right int) *TreeNode {
		if left > right {
			return nil
		}
		value := preorder[preorderIndex]
		preorderIndex++
		node := &TreeNode{Val: value}
		split := inorderIndex[value]
		node.Left = build(left, split-1)
		node.Right = build(split+1, right)
		return node
	}
	return build(0, len(inorder)-1)
}

// ===================================================================
// 32. Cache Design
// ===================================================================

// LeastRecentlyUsedCacheNode participates in a doubly linked recency list.
type LeastRecentlyUsedCacheNode struct {
	key   int
	value int
	prev  *LeastRecentlyUsedCacheNode
	next  *LeastRecentlyUsedCacheNode
}

// LeastRecentlyUsedCache combines O(1) map lookup with O(1) recency updates.
// The head and tail are sentinel nodes, so insertion/removal needs no nil cases.
type LeastRecentlyUsedCache struct {
	capacity int
	nodes    map[int]*LeastRecentlyUsedCacheNode
	head     *LeastRecentlyUsedCacheNode
	tail     *LeastRecentlyUsedCacheNode
}

// newLeastRecentlyUsedCache creates a least-recently-used cache. A map gives O(1) key
// lookup; a doubly linked list orders nodes from least recent near head to most recent
// near tail.
func newLeastRecentlyUsedCache(capacity int) *LeastRecentlyUsedCache {
	head, tail := &LeastRecentlyUsedCacheNode{}, &LeastRecentlyUsedCacheNode{}
	head.next = tail
	tail.prev = head
	return &LeastRecentlyUsedCache{
		capacity: capacity,
		nodes:    make(map[int]*LeastRecentlyUsedCacheNode),
		head:     head,
		tail:     tail,
	}
}

// remove detaches one cache node from the doubly linked recency list.
func (c *LeastRecentlyUsedCache) remove(node *LeastRecentlyUsedCacheNode) {
	node.prev.next = node.next
	node.next.prev = node.prev
}

// addMostRecent inserts one cache node immediately before the tail sentinel.
func (c *LeastRecentlyUsedCache) addMostRecent(node *LeastRecentlyUsedCacheNode) {
	previous := c.tail.prev
	node.prev, node.next = previous, c.tail
	previous.next = node
	c.tail.prev = node
}

// get returns a cached value or -1 when absent. A hit moves its node to the most-recent
// end in O(1).
func (c *LeastRecentlyUsedCache) get(key int) int {
	node, ok := c.nodes[key]
	if !ok {
		return -1
	}
	c.remove(node)
	c.addMostRecent(node)
	return node.value
}

// put inserts or replaces a value, marks it most recent, and evicts the least-recent
// node when capacity is exceeded. All operations are O(1).
func (c *LeastRecentlyUsedCache) put(key, value int) {
	if node, ok := c.nodes[key]; ok {
		c.remove(node)
		delete(c.nodes, key)
	}

	node := &LeastRecentlyUsedCacheNode{key: key, value: value}
	c.nodes[key] = node
	c.addMostRecent(node)

	if len(c.nodes) > c.capacity {
		victim := c.head.next
		c.remove(victim)
		delete(c.nodes, victim.key)
	}
}

// ===================================================================
// 33. String, Number, and Bit Extras
// ===================================================================

// addDecimalStrings adds non-negative base-10 integers represented as strings,
// processing digits from right to left with carry.
// Requires: import "slices"
func addDecimalStrings(a, b string) string {
	i, j, carry := len(a)-1, len(b)-1, 0
	answer := make([]byte, 0, max(len(a), len(b))+1)
	for i >= 0 || j >= 0 || carry > 0 {
		x, y := 0, 0
		if i >= 0 {
			x = int(a[i] - '0')
			i--
		}
		if j >= 0 {
			y = int(b[j] - '0')
			j--
		}
		total := x + y + carry
		answer = append(answer, byte(total%10)+'0')
		carry = total / 10
	}
	slices.Reverse(answer)
	return string(answer)
}

// compareVersionNumbers compares dot-separated non-negative integer components and
// treats missing trailing components as zero.
// Requires: import "strconv"
// Requires: import "strings"
func compareVersionNumbers(first, second string) int {
	a := strings.Split(first, ".")
	b := strings.Split(second, ".")
	for index := 0; index < max(len(a), len(b)); index++ {
		x, y := 0, 0
		if index < len(a) {
			x, _ = strconv.Atoi(a[index])
		}
		if index < len(b) {
			y, _ = strconv.Atoi(b[index])
		}
		if x < y {
			return -1
		}
		if x > y {
			return 1
		}
	}
	return 0
}

// base10Digits returns the decimal digits of an integer in most-significant-first
// order.
// Requires: import "slices"
func base10Digits(n int) []int {
	if n < 0 {
		n = -n
	}
	if n == 0 {
		return []int{0}
	}
	digits := make([]int, 0)
	for n > 0 {
		digits = append(digits, n%10)
		n /= 10
	}
	slices.Reverse(digits)
	return digits
}

// isPrimeUsingTrialDivision tests divisors only through sqrt(n), written factor <=
// n/factor to avoid factor*factor overflow. After handling 2, only odd candidates are
// needed. Time O(sqrt(n)); space O(1).
func isPrimeUsingTrialDivision(n int) bool {
	if n < 2 {
		return false
	}
	if n%2 == 0 {
		return n == 2
	}
	for factor := 3; factor <= n/factor; factor += 2 {
		if n%factor == 0 {
			return false
		}
	}
	return true
}

// primeTableUsingSieveOfEratosthenes returns a bool table from 0 through n. Each
// discovered prime marks multiples starting at prime^2 because smaller multiples were
// handled earlier. Time O(n log log n); space O(n).
func primeTableUsingSieveOfEratosthenes(n int) []bool {
	isPrime := make([]bool, n+1)
	for value := 2; value <= n; value++ {
		isPrime[value] = true
	}
	for prime := 2; prime <= n/prime; prime++ {
		if !isPrime[prime] {
			continue
		}
		for multiple := prime * prime; multiple <= n; multiple += prime {
			isPrime[multiple] = false
		}
	}
	return isPrime
}

// singleUnpairedNumberUsingExclusiveOr assumes every value appears twice except one.
// Exclusive OR cancels equal pairs (x XOR x = 0) and zero changes nothing, leaving the
// unpaired value. Time O(n); space O(1).
func singleUnpairedNumberUsingExclusiveOr(nums []int) int {
	answer := 0
	for _, value := range nums {
		answer ^= value
	}
	return answer
}

// runLengthEncode converts each consecutive byte run to the byte followed by its
// decimal count, so "aaabb" becomes "a3b2". It is byte-oriented rather than
// Unicode-rune-oriented. Time O(n).
// Requires: import "strconv"
// Requires: import "strings"
func runLengthEncode(s string) string {
	if s == "" {
		return ""
	}
	var builder strings.Builder
	for start := 0; start < len(s); {
		end := start + 1
		for end < len(s) && s[end] == s[start] {
			end++
		}
		builder.WriteByte(s[start])
		builder.WriteString(strconv.Itoa(end - start))
		start = end
	}
	return builder.String()
}

// intFromBase10Digits combines decimal digits into an integer; false reports a value
// outside 0 through 9.
func intFromBase10Digits(digits []int) (int, bool) {
	value := 0
	for _, digit := range digits {
		if digit < 0 || digit > 9 {
			return 0, false
		}
		value = value*10 + digit
	}
	return value, true
}

// primeFactorCounts returns prime factors mapped to their exponents. Repeated trial
// division removes each factor before moving on; any remainder greater than one is
// prime. Time O(sqrt(n)) worst case.
func primeFactorCounts(n int) map[int]int {
	factors := make(map[int]int)
	if n < 0 {
		n = -n
	}
	for factor := 2; factor <= n/factor; factor++ {
		for n%factor == 0 {
			factors[factor]++
			n /= factor
		}
	}
	if n > 1 {
		factors[n]++
	}
	return factors
}

// ===================================================================
// 34. Quick Reference and Go-Specific Gotchas
// ===================================================================

/*
Quick reference: choose the operation before recalling punctuation.

Terms used below:
- Lower bound: first sorted index whose value is at least the target.
- Min-heap: priority queue that removes the smallest item first.
- heap.Interface: the five Len/Less/Swap/Push/Pop methods required by
  container/heap.
- Backtracking path: the current partial choices in recursive search.

Task                         Go 1.21+ form
Empty slice                  values := []T{} or make([]T, 0, capacity)
Append / pop stack           s = append(s, x) / s = s[:len(s)-1]
Independent slice copy       clone := slices.Clone(s)
Map lookup                   value, exists := m[key]
Readable set membership      set := map[T]bool{}; if set[value] { ... }
Key-only set                 set := map[T]struct{}{}; _, ok := set[value]
Sorted copy                  clone := slices.Clone(s); slices.Sort(clone)
Lower bound                  sort.Search(len(s), func(i int) bool { return s[i] >= x })
Queue                        queue + head index; mark visited before enqueue
Min-heap                     implement heap.Interface; heap.Push/heap.Pop use any
Mutable string assembly      strings.Builder or []byte
Unicode-safe characters      runes := []rune(text)
Integer min / max            min(a, b) / max(a, b)
Clear bit                    value &^= 1 << bit
Save backtracking path       answer = append(answer, slices.Clone(path))

Go-specific gotchas: symptom -> interview-safe default.

len(text) counts bytes        -> use []rune or utf8 helpers for Unicode
copy := original slice       -> shares a backing array; use slices.Clone
append(slice, x) ignored     -> assign the returned slice header
missing map key looks valid  -> use comma-ok when zero and missing differ
write to nil map             -> initialize with make or a literal first
range value mutation         -> mutate collection[index], not the copied value
map output changes order     -> collect and sort keys when order matters
math.Max on integers         -> use built-in max on Go 1.21+
~value for bitwise NOT       -> Go spells unary complement ^value
close channel from receiver  -> the sending side normally owns close
interface holding typed nil  -> dynamic type makes the interface non-nil
heap.Pop result stays any     -> value := heap.Pop(&h).(YourConcreteType)
*/

